// ================================================================== the spec document: FLvibed as BUILT (25 Oct 2026)
// The living spec of FLvibed as a whole (the owner, 25 Oct 2026 evening): every feature it adds, how a player installs
// and uses it, and what is not implemented yet. Static, reviewed content for two readers: a player (the lead, the
// captions) and the developer (the "For developers" blocks: rules, sizes in fractions of the screen height H, settings
// keys, files, sources). The options rows and the bindings are NOT here: they render live from the spec (DEFAULT_SPEC /
// the owner's ui/spec), so the owner's values show.
// Block types: p (html), cmp (a drag slider: cl = left, h2 = right, ll / rl their labels), gal (captures), settings (row
// keys from the spec), table, dev (an expandable developer block, html), binds (the pad layout tables from the spec),
// keys (K&M), tabs, family. The Input switch (part3c_doc.js): a block's `only: 'pad'|'km'`, its `km: {...}` variant, a
// gallery item's `km`, and each section's `dv` note ({same} or {pad, km}).
// Status words in tables: <span class="st ok">verified</span>, <span class="st wip">..</span>, <span class="st no">not tested</span>.
// Images: img/cap/*.jpg, written by spec_images.py from the release-build captures.
const CAP = n => 'img/cap/' + n + '.jpg';
const OK = t => `<span class="st ok">${t || 'verified'}</span>`;
const WIP = t => `<span class="st wip">${t || 'work in progress'}</span>`;
const NO = t => `<span class="st no">${t || 'not tested'}</span>`;
// New in the 0.2.0 release (CHANGELOG.md "0.2.0"): the "New in 0.2.0" section lists them; in the other sections UP()
// marks a feature 0.1.0 did not have. The first change after 0.2.0 turns the section back into "Upcoming" (since 0.2.0).
const UP = t => `<span class="st up" title="New in 0.2.0 (0.1.0 did not have it)">${t || 'new in 0.2.0'}</span>`;
const DOC = [
  { id: 'overview', nav: 'Overview', title: 'FLvibed at a glance',
    lead: `FLvibed is a free mod for Freelancer (2003) and Freelancer: HD Edition that lets you play the whole game with a controller (or keep your keyboard and mouse), read every spoken line as a subtitle, and see the movies fitted to your screen: one file in the game folder, nothing else to install. <b>0.2.5</b> made HUD 2 calm and contextual: the screen belongs to space until something needs your attention. <b>0.2.6</b> added weapon-group editing, nav map zoom and NeuroNet reach on the pad, a tractor that takes one item or all, and a right stick that targets the nearest enemy first. <b>0.2.7</b> (4 Nov 2026) fires the torpedo from a held missile button in every preset and under the autopilot, plays the Neural Net lines under HUD 2 and lets the bumpers reach every room on stations (see "New in 0.2.7"). In detail: FLvibed is one mod for Freelancer (2003) / Freelancer: HD Edition that adds what the game never had: <b>full Xbox-controller play</b> with a controller-first interface (its own flight HUD, button prompts on every screen, glyphs for Xbox, PlayStation and Switch pads), <b>dialogue subtitles</b> with speaker names and portraits, <b>better movies</b> (they fit the screen, the intros are subtitled), screen-edge <b>hit effects</b>, and an <b>Advanced Autopilot</b> that can fly and fight for you. It is one file, <code>FLvibed.dll</code>, with nothing else to install, and keyboard and mouse keep working exactly as before.`,
    dv: { pad: 'With a controller FLvibed shows its controller interface: HUD 2 in flight, glyph prompts on every screen. Choose K&amp;M above to see the page as a keyboard-and-mouse player.', km: 'With keyboard and mouse the game looks and plays as it always did, plus the subtitles, the hit effects, the autopilot button and the options page; HUD 2 is the default here too, with keycaps and clickable chips.' },
    blocks: [
      { t: 'table', title: 'What FLvibed adds', head: ['Feature', 'What you get', 'State'], rows: [
        ['<b>Controller play</b>', 'Fly, fight, dock, trade and use every menu with an XInput pad; three flight layouts; holds, doubles, an on-screen keyboard; switch devices at any moment.', OK() + ' virtual pad; flight and combat on the real Elite pad'],
        ['<b>Flight HUD 2</b>', 'FLvibed\'s own flight HUD: the ship\'s state on a ring around the reticle, only what matters now. Or keep the game\'s HUD with glyph badges.', OK()],
        ['<b>HUD 2 in the menus and bases</b>', 'HUD 2\'s look over the menus, bases, dealers and dialogs, part of HUD 2 and on by default.', OK()],
        ['<b>Aim</b>', 'Gimbal aim (the stick steers, the reticle locks onto the target\'s lead) or a free reticle with aim assists.', OK()],
        ['<b>Hit effects</b>', 'Screen-edge effects in your shield\'s own look when you are hit, a hull pattern when the shield is down, reticle pulses for the autopilot and consumables (on by default, can be turned off).', OK()],
        ['<b>Subtitles</b>', 'Every spoken line with the speaker\'s name, colour and portrait, timed on the speaker\'s words; Neural Net lines by severity; chatter in the chat window.', OK() + ' (dialogue text fully reviewed by ear; the 19 scene mixes still under review)'],
        ['<b>Movies</b>', 'Startup movies fit the screen with their aspect; the intros are subtitled.', OK() + ' (borderless and windowed, HDE and vanilla)'],
        ['<b>Advanced Autopilot</b>', 'Flies missions, travels, docks and fights by one set of rules; one start and a goal panel on the pad and on keyboard + mouse alike; pickers on the pad.', WIP()],
        ['<b>Speedrun mode</b>', 'An in-game timer with a split per story checkpoint, fed to LiveSplit.', OK() + ' (live split from a real kill not observed)'],
        ['<b>Options page</b>', 'Every setting on one page in the game\'s own Options screen.', OK()],
        ['<b>Multiplayer</b>', 'On a server FLvibed works as in single player (HUD 2, targeting, the subtitles\' names, job-board missions), and the server decides what the autopilot may do (Install, Not implemented yet).', UP() + ' ' + OK('local HDE and vanilla servers')],
        ['<b>Runs on</b>', 'HD Edition 0.7.1 (the tested base) and the original Freelancer 1.1 with a decrypted exe; beside FLUF on the original game (its windows stay on top, FLvibed steps around them); a borderless window where nothing else provides one.', OK() + ' (Install, With FLUF)'],
      ] },
      { t: 'table', title: 'Three interface layers, each with its own switch', head: ['Layer', 'What you see', 'Setting (default)'], rows: [
        ['<b>Flight HUD 2</b>', 'FLvibed\'s own flight HUD: your shield, hull and power on a ring around the reticle, the target top right, your ship bottom left, your weapons and consumables bottom right.', '<code>hud_style</code> = HUD 2 ALWAYS (default: controller and keyboard and mouse)'],
        ['<b>Classic HUD (pad layer)</b>', 'The game\'s own flight HUD, with controller glyph badges on its buttons and a short list of what you can do now.', '<code>hud_style</code> = CLASSIC'],
        ['<b>HUD 2 in the menus and bases</b>', 'HUD 2\'s look over the menus, bases, dealers and dialogs: glass panels, a context strip, name cards, price words. The game\'s screens and buttons stay as they are. Part of HUD 2: on whenever HUD 2 is on; the row <i>Menus and rooms look</i> (advanced) switches it back to the game\'s own look.', '<code>ui_style</code> = HUD 2 (default)'],
      ] },
      { t: 'p', html: `<b>Both devices always work.</b> Touch the controller and the controller interface appears in one frame; move the mouse or press a key and the game's own interface is back. HUD 2 is the default for both: keyboard and mouse players get it too, with keycaps and clickable chips. The HUD row set to Classic gives the game\'s own HUD (and menus) back.` },
      { t: 'p', html: `<b>Reading this page:</b> the <b>Input</b> buttons at the top switch the captures, the button tables (glyphs or keycaps) and the per-device notes; each section says what changes. The comparisons drag (left label vs right label). Captures are from the release build at 3840x2160 unless noted. A ${UP()} tag marks what the earlier 0.1.0 release did not have (the next section lists all of it). The last section lists honestly what is not implemented yet.` },
      { t: 'dev', html: `<p><b>One DLL, modules that work alone and together:</b> <code>FLvibed.dll</code> = <code>core\\flvibed.cpp</code> (DllMain starts the enabled modules, subtitles then controller) + each module's host (hooks) and, in the release build, its logic linked in (<code>FLV_STATIC</code>). Switches: <code>EXE\\FLvibed.ini</code> [Modules] <code>subtitles</code> / <code>controller</code> (read at game start; the GENERAL tab's rows). Static C runtime (<code>build.cmd</code> <code>/MT</code>): only Windows and the game. Any resolution, aspect ratio and DPI (sizes in fractions of H); Borderless Windowed is the main mode. Every Freelancer.exe address is a signed symbol (<code>core\\flexe.h</code>); a mismatch fails closed per feature.</p>
<p>Documents: <code>docs\\UI_HUD2.md</code> (flight HUD 2), <code>docs\\UI_HUD2_EXTENDED.md</code> (the non-flight skin, the bottom lane), <code>docs\\UI_PLAN.md</code> 6 (controller UI), <code>docs\\UI_BUILD.md</code> (architecture, status, gaps), <code>controller\\docs\\HUD_CUES.md</code>, <code>FLIGHT_AIM.md</code>, <code>AUTOPILOT.md</code> / <code>AUTOPILOT_UX.md</code>, <code>subtitles\\docs\\DISPLAY_PLAN.md</code>, <code>docs\\SETTINGS.md</code> (generated: every key), <code>docs\\UI_SPEC.json</code><span class="edonly"> (this page's spec = the artifact's <code>ui/spec</code>)</span>, <code>core\\ui_meta.h</code> (generated from it by <code>tools\\ui_meta.py</code>). This page's source: <code>tools\\uimock\\</code> (README: build, publish, the standing rules).</p>
<p>Rules that bind every UI part: sizes in fractions of H (safe margin 0.05 W at the sides, 0.05 H top and bottom); one text-fit rule (<code>core\\game\\textfit.h</code>: a text that does not fit its box steps down only as far as needed, to the floor, and only then is cut with an ellipsis or wraps where its box takes lines) and a legibility floor of 0.024 H, never under 14 px, whatever <code>text_size</code> / <code>hud_scale</code> say; readers fail closed (unknown = nothing shown, never a guess); the game's own data first; a switch restores every byte at once; event-driven, no polling. Budgets: flight HUD 2 0.12 ms per frame in a release fight at 4K; HUD 2 in the menus 67-84 us per frame at 4K.</p>` },
    ] },

  { id: 'upcoming', nav: 'New in 0.2.7', title: 'New in 0.2.7: what changed since 0.1.0',
    lead: `The released build is <b>FLvibed 0.2.7</b> (4 Nov 2026). The first group is what 0.2.7 changed; the groups after it are what 0.2.6 (4 Nov 2026), 0.2.5 (2 Nov 2026) and 0.2.0 (1 Nov 2026) changed since 0.1.0 (26 Oct 2026); in the other sections a ${UP()} tag marks what is new since 0.1.0. The list follows <code>CHANGELOG.md</code> ("0.2.7", "0.2.6", "0.2.5" and "0.2.0"). The controller features were tested on a virtual pad, not a real one.`,
    dv: { same: 'The list covers every device; the controller-only changes say so.' },
    blocks: [
      { t: 'table', title: 'In 0.2.7', head: ['Highlight', 'Where'], rows: [
        ['<b>Neural Net lines under HUD 2:</b> Objective Reached, Tractor Failure, the docking lines and the rest play in flight, voice and subtitle. With HUD 2 on, only the first one played and the others waited until the NeuroNet opened (GitHub issue 8).', 'Flight HUD 2'],
        ['<b>The bumpers reach every room on stations:</b> on the pad, LB / RB step through every room in a base. On stations the Trader and Equipment rooms dropped out, which sent you back to the wrong room or never reached them (GitHub issue 9).', 'Menus and bases'],
        ['<b>Dealer screens under HUD 2:</b> an item you cannot buy (no free hardpoint, say) keeps the full centre panel and the infocard\'s backing, so its text fits and stays readable, and the prompts stay off it (GitHub issue 10). The comparison with your mounted gun uses the panel\'s whole width, and a long heading takes a second line instead of being cut.', 'Menus and bases'],
        ['<b>Prompts in bases:</b> on the pad they hold their place while a subtitle shows. This is a guard against the flicker reported with Neural Net subtitles at the dealers; the flicker could not be reproduced, so it is not proven fixed (GitHub issue 10).', 'Menus and bases'],
        ['<b>HUD 2\'s chat in in-flight cutscenes:</b> it keeps its cards through docking, launching and mission scenes. The game\'s plain chat window came back in them, with bare lines at the screen\'s edge.', 'Flight HUD 2'],
        ['<b>Long credit counts:</b> HUD 2\'s ship panel grows, so CREDITS stays whole and the number no longer clips. Only past the panel\'s widest does the word shorten to CR.', 'Flight HUD 2'],
        ['<b>Invert Y in turret view:</b> on the pad, turret view follows Invert Y on the right stick, FLvibed\'s setting and the game\'s own alike; so does the aim cursor of the ASSISTED preset (GitHub issue 6).', 'Controls'],
        ['<b>Torpedoes in every preset:</b> holding the missile button fires the torpedo in every preset and while the autopilot flies: RB in ASSISTED, B in ACE. Before, it only worked in FREELANCER with you flying (GitHub issue 7).', 'Controls'],
        ['<b>Cruise disruptors:</b> the same hold fires a cruise disruptor when the ship has one and no torpedo, and HUD 2\'s row says HOLD for it. The action wheel\'s entry stays (GitHub issue 7).', 'Controls'],
        ['With one item in reach and targeted, HUD 2\'s prompts no longer offer it on both A and X.', 'Flight HUD 2'],
        ['HUD 2\'s tractor prompts fade like the others while you move; the changing range kept them on screen.', 'Flight HUD 2'],
        ['HUD 2, keyboard: NEAREST ENEMY now shows the game\'s nearest-enemy key, not the next-enemy key.', 'Flight HUD 2'],
        ['HUD 2\'s enemies cue stays off during cinematic scenes (docking, lanes, jumps).', 'Flight HUD 2'],
        ['Classic HUD, ASSISTED preset: no tractor prompt on A, where A starts the autopilot.', 'Classic HUD'],
        ['On the pad, if the game refuses the enemy the right stick picked, the next click takes another one. More than 32 enemies near no longer stops the clicks from moving on.', 'Controls'],
        ['<b>Enemies sitting idle (GitHub issue 3) is still not fixed.</b> 0.2.7 changes nothing there; FLvibed keeps logging the stalled hostile ships.', 'Not implemented yet'],
      ] },
      { t: 'table', title: 'In 0.2.6', head: ['Highlight', 'Where'], rows: [
        ['<b>The NeuroNet on the pad in flight:</b> the cursor reaches the box\'s buttons (mission log, inventory, player info, help) and the nav map answers it, whoever flies (the pad, the autopilot or nobody); the HUD\'s cursor block for aiming stops while a NeuroNet window is open.', 'Controls'],
        ['<b>Nav map zoom on the triggers</b> (in space and docked): RT zooms in on what lies under the cursor, LT zooms out, from the sector to the system to the universe. Before, they only worked with something already selected.', 'Controls'],
        ['<b>Weapon groups on the pad:</b> EDIT GROUPS in the action wheel lists the ship\'s guns: A switches a gun on or off in the group, D-pad up / down picks the gun, LB / RB the group, B is done. Holding Y now skips groups without guns.', 'Controls'],
        ['<b>Torpedoes in HUD 2\'s weapons list:</b> a row of their own with the count and how to fire them (HOLD on the pad, the key in the keyboard form). A ship with torpedoes shows two group rows instead of three, the active group always among them.', 'Flight HUD 2'],
        ['<b>Red hull meters</b> (the game\'s own HUD colour) on the ring and the target card. A low shield keeps its blue and flashes red at 25 % and below; a low hull flashes bright red with a soft bloom at 25 % and below. <code>shield_cue</code> and <code>hull_cue</code> switch the flashes off.', 'Flight HUD 2'],
        ['<b>The tractor, one item or all:</b> A tractors one item (the targeted loot, with nothing targeted the nearest), X tractors everything in reach; before, both pulled everything. The prompts say which does what and name the item with its range (<code>A TRACTOR DRAIL &middot; 730 m</code>, <code>X TRACTOR ALL 9</code>), in HUD 2 and the classic HUD. Loot your hold cannot take is no longer offered. Keyboard: HUD 2 shows the key for one item and the key for all loot.', 'Flight HUD 2'],
        ['<b>The right stick\'s click targets the nearest enemy first</b> (within 10 km). Clicking again within three seconds takes the next enemy, and so on through all of them; after a pause it starts again from the nearest. With no enemy near it still targets what is in front of the reticle. A double click still clears the target.', 'Flight & aim'],
        ['<b>Enemies nearby cue</b> (pad): with enemies near and nothing targeted, the top-right corner says how many enemies are near and shows the right stick\'s TARGET NEAREST.', 'Flight HUD 2'],
        ['<b>Stalled maneuvers:</b> when a formation, goto or dock stalls, FLvibed now leaves the maneuver and starts it again, the way that got a player out of it. Starting the same formation again on a ship that was still in it did nothing. The row <i>Restart stalled maneuvers</i> (<code>maneuver_watchdog</code>) switches it.', 'Controls'],
        ['<b>Enemies sitting idle (GitHub issue 3) is not fixed.</b> When a hostile ship near you stops moving, FLvibed now writes what the game says about it to <code>EXE\\FLvibed_npc_stalls.log</code>, so the cause can be found. It only reads and changes nothing in the game; <code>npc_stall_log</code> 0 switches it off. The cause is being investigated.', 'Not implemented yet'],
        ['<b>The NeuroNet box beside HUD 2:</b> the game\'s box could stay on screen next to HUD 2 after loading a save. It now hides again. This could not be reproduced in 44 test loads; if it comes back, <code>FLController.log</code> names the window that kept it up.', 'Flight HUD 2'],
        ['<b>Autopilot with HUD 2 on:</b> it read the guns\' fire slots from their hardpoint names, because HUD 2 hides the game\'s list. On ships where the two orders differ it could leave a gun idle or fire a launcher\'s slot. It now reads the game\'s list.', 'Autopilot'],
      ] },
      { t: 'table', title: 'In 0.2.5', head: ['Highlight', 'Where'], rows: [
        ['<b>Contextual HUD (the new default):</b> the HUD setting has two modes, FULL and CONTEXTUAL. Contextual fades HUD 2 out while you fly calmly and brings each part back for four seconds when it matters: the ring and speed when you steer or boost, the target card when you switch targets, the weapons when you fire, the objectives when they change. Alerts, low shield or hull, incoming missiles and fights always show. The old "calm dims" and "minimal" modes are gone; a saved 2 reads as contextual.', 'Flight HUD 2'],
        ['Mouse steering and cursor movement in flight wake the reticle and speed, as the stick does.', 'Flight HUD 2'],
        ['<b>Button prompts no longer scroll:</b> a label too long for its place wraps onto two lines in a slightly smaller, still readable font. Ship and weapon names keep their scrolling.', 'Flight HUD 2'],
        ['Context prompts show when they change or right after you act (dock, cruise, a target, a maneuver), stay four seconds and fade out. The setting <code>hud_prompts</code> (0 = always shown, as in 0.2.0) brings back the old way.', 'Flight HUD 2'],
        ['When a mission locks your maneuvers (for example while you fly in Brandt\'s formation in the first mission), pressing free flight, formation, dock or goto shows LOCKED BY THE MISSION at the top instead of silently doing nothing.', 'Flight HUD 2'],
        ['HUD 2\'s target card, contact list, ship panel and loadout panel are only as wide as what they show (up to their old widths), easing gently when the content changes.', 'Flight HUD 2'],
        ['<b>HUD 2\'s look now also covers the main menu and the mission / tutorial popups</b> (same layout and controls; the classic look is unchanged).', 'Menus and bases'],
        ['<b>Panels sized to their content:</b> the NeuroNet readout and the target picker are only as large as what they show (up to their old sizes); text uses the space a panel keeps before scrolling.', 'Flight HUD 2'],
        ['The mouse cursor hides in flight with the contextual HUD when you leave the mouse alone, and returns as soon as you move it (at once in the pause menu and other non-flight screens).', 'Flight HUD 2'],
        ['<b>The action wheel is more compact:</b> two-word commands on two lines, a smaller ring whose plates clear the reticle and each other, and no repeated name under the reticle. Under HUD 2 each command sits on a HUD 2 plate over a see-through disc; under the classic HUD it uses the game\'s own panel look, lighter than before.', 'Controls, Flight HUD 2'],
        ['<b>Subtitles:</b> the dialogue panel at the top in flight is 10 % smaller (rooms, story scenes and movies keep their size); when lines stack, the newest stays full size and only the older ones shrink, more gently; the side chat is smaller by default (Normal), the old size is Large (<code>chat_size</code>).', 'Subtitles &amp; movies'],
        ['<b>Formation, goto and dock no longer stay stuck:</b> if your ship stalls during one, FLvibed restarts the maneuver and logs what happened (setting <code>maneuver_watchdog</code>, on by default).', 'Autopilot'],
        ['<b>Panel heights fit their rows:</b> the ship panel and the loadout panel are only as tall as their rows, so a short loadout no longer leaves an empty area (the two bottom panels are no longer equal in height).', 'Flight HUD 2'],
        ['The game\'s cursor also hides in flight while you fly with the controller (after 3 s; any real mouse movement brings it back).', 'Flight HUD 2'],
        ['The contextual HUD also fades in turret view, and pressing any fire button (even with nothing able to fire) brings back the whole HUD.', 'Flight HUD 2'],
      ] },
      { t: 'table', title: 'In 0.2.0: HUD 2, everywhere', head: ['Highlight', 'Where'], rows: [
        ['<b>HUD 2 is the default</b> with the pad <b>and</b> with keyboard and mouse, and its look carries over the menus, bases, dealers and dialogs. Setting the HUD row to Classic brings the game\'s own HUD and screens back.', 'Flight HUD 2, Menus and bases'],
        ['<b>The bottom of the HUD was rearranged:</b> the lower centre stays clear so your ship is never covered, button prompts sit in two lanes (bottom left and right), a name too long for its room scrolls like a public display, and CRUISE ON and the cruise countdown show inside the ring.', 'Flight HUD 2'],
        ['Nothing overlaps inside a panel or card any more; the ship and loadout panels share one height.', 'Flight HUD 2, Menus and bases'],
        ['<b>Closer to the edges:</b> 3 % margins instead of 5 %, so more of the view is yours.', 'Flight HUD 2'],
        ['<b>Focus layout</b> (experimental, among the options page\'s advanced rows): in calm flight no ring, two thin shield and hull arcs and the instruments at the screen\'s edges.', 'Flight HUD 2, Options page'],
      ] },
      { t: 'table', title: 'In 0.2.0: Feel and feedback', head: ['Highlight', 'Where'], rows: [
        ['<b>Hit effects are on by default:</b> screen-edge cues in your shield\'s and hull\'s look when you are hit, and crosshair pulses for the autopilot and consumables. Each can be switched off.', 'Hit effects'],
        ['<b>Rumble on the pad:</b> a hit (the hull heavier than the shield), a failing shield, and two ticks when one of the game\'s boxes waits for you. Strength under Rumble, 0 = off; only while you play with the pad and the game is in front. ' + NO() + ' verified by the test harness so far, not on a real pad yet.', 'Controls, Options page'],
        ['The autopilot\'s hints for players who have not used it yet are on by default.', 'Autopilot'],
      ] },
      { t: 'table', title: 'In 0.2.0: Subtitles and story', head: ['Highlight', 'Where'], rows: [
        ['<b>Every dialogue line was reviewed by ear</b> against the recordings: names, words and the bracketed sound cues.', 'Subtitles &amp; movies'],
        ['<b>The 19 room scenes</b> recorded as one track (the landing at Manhattan, Lonnigan on the pad, Tekagi\'s garden, ...) are now subtitled, with speaker names and word-timed pages. ' + NO('under review') + ' a few lines may differ slightly.', 'Subtitles &amp; movies'],
        ['<b>Stacked speakers shrink smoothly</b> (to 70 % at most, the new row <i>Stacked lines shrink to</i>) so the stack keeps about one line\'s height: no big covered parts of the picture at 4:3 or in story scenes.', 'Subtitles &amp; movies'],
        ['<b>A red marker</b> before a hostile speaker\'s name (can be turned off).', 'Subtitles &amp; movies'],
        ['The HD Edition intro now subtitles its opening radio exchange: five lines that were missing.', 'Subtitles &amp; movies'],
        ['With mods that replace a scene\'s recording (Crossfire ships some), the original scene\'s lines no longer show over it.', 'Subtitles &amp; movies, With FLUF'],
      ] },
      { t: 'table', title: 'In 0.2.0: Controller', head: ['Highlight', 'Where'], rows: [
        ['<b>Confirm with</b> works: set it to the right button (Nintendo layout) and every menu, list, picker and popup accepts with it and goes back with the bottom one, prompts included.', 'Controls'],
        ['Holding RB for a torpedo no longer also launches a missile; a tap launches the missiles on release.', 'Controls'],
        ['Hold X to look around from the turret camera while the autopilot keeps flying and fighting.', 'Flight &amp; aim, Autopilot'],
        ['Dealers: B on the BUY / SELL button or the quantity slider steps back to the item instead of closing the dealer.', 'Menus and bases'],
        ['The pad drives the main menu, the multiplayer LAN / INTERNET question and the death dialog directly, plus the multiplayer server and character lists (D-pad to pick, A to connect, Y for a new character).', 'Menus and bases, Not implemented yet'],
        ['<b>SDL3 backend</b> (opt-in, <code>pad_backend = 1</code>, experimental): meant to read PlayStation and Switch pads directly, with their own prompts. ' + NO() + ' not tested with those pads yet; XInput stays the default.', 'Options page, Controls'],
        ['With another window in front, the pad is ignored in menus and flight alike and does not vibrate.', 'Controls'],
      ] },
      { t: 'table', title: 'In 0.2.0: Autopilot (work in progress)', head: ['Highlight', 'Where'], rows: [
        ['<b>Fights for time on target:</b> it finishes the enemy it is on, handles head-on passes, learns the best standoff distance per pair of ships and leads its missiles. Every gun fires on stations and generators.', 'Autopilot'],
        ['It rolls toward more guns and steers true when the ship is banked; follows and escorts without the flicker, and a Hold now defends itself.', 'Autopilot'],
        ['<b>Smarter in the details:</b> escapes flown as escapes, huge targets (the Dyson city\'s generators) approached in a coast, fewer missiles bursting on yourself, a fast dock that no longer rams the bay, fight odds that count shield damage.', 'Autopilot'],
        ['<b>A plain start on a targeted base, gate or hole</b> travels there by the game\'s best path, lanes included.', 'Autopilot'],
        ['On the original Freelancer 1.1 it now knows the minefields, dangerous zones and planets\' docking rings.', 'Autopilot, Install'],
      ] },
      { t: 'table', title: 'In 0.2.0: Multiplayer and compatibility', head: ['Highlight', 'Where'], rows: [
        ['<b>Multiplayer</b> (experimental) works, tested on a local HD Edition server: HUD 2, targeting, subtitle speaker names, missions and job boards, and the autopilot, as far as the server allows (<code>[flvibed autopilot=on|travel|off]</code>, else the setting <code>mp_autopilot</code>). Online it leans to survival. Server hosts get an FLHook plugin (<code>server/flhook/</code>).', 'With FLUF, Not implemented yet'],
        ['<b>Windows 7 SP1 and up:</b> no function newer than Windows 7 is imported any more. ' + NO() + ' checked, not yet played there.', 'Install'],
        ['The original game\'s LAN list connects to local servers; the chat never shows an unfilled name template.', 'Install'],
        ['The game no longer stops drawing for seconds to minutes.', 'Install'],
      ] },
      { t: 'table', title: 'In 0.2.0: Under the hood', head: ['Highlight', 'Where'], rows: [
        ['FLvibed\'s code is now licensed <b>GPL-3.0</b>, like the subtitle data.', 'Install'],
        ['Reads more of the game\'s data from its binary files, so the original 1.1 gets the same zone names, prices and pilots.', 'Install'],
        ['The autopilot no longer writes a flight trace into the game folder (<code>motion_log = 1</code> is the debugging aid).', 'Autopilot'],
      ] },
      { t: 'table', title: 'Updating from 0.1.0', head: ['Highlight', 'Where'], rows: [
        ['<b>On its first start 0.2.0 puts every FLvibed setting back to its default</b>, so you get the new defaults. Your old files are kept beside the new ones as <code>FLvibed.ini.before-0.2.0</code> (and the same for <code>FLController.ini</code> and <code>FLSubtitles.ini</code>). Your per-save game modes and speedrun bests stay.', 'Install'],
      ] },
      { t: 'table', title: 'In detail: the full change list', head: ['Change', 'Where'], rows: [
        ['<i>The tables below list every change one by one, small ones included, from the CHANGELOG.</i>', ''],
      ] },
      { t: 'table', title: 'Controller and HUD', head: ['Change', 'Where'], rows: [
        ['<b>HUD 2 is the default</b> for the controller and for keyboard and mouse, and its look over the menus and bases (formerly Extended HUD 2) is part of it. The HUD row set to Classic gives the game\'s own HUD and menus back; the advanced row <i>Menus and rooms look</i> keeps the game\'s own look in the menus only.', 'Flight HUD 2, Menus and bases'],
        ['<b>Confirm with</b> works: set to RIGHT BUTTON (NINTENDO), every menu, list, picker and popup accepts with the right face button and goes back with the bottom one, and the prompts show it so; flight keeps its layout. (In 0.1.0 the row was there but did nothing.)', 'Controls'],
        ['<b>Vibration:</b> the pad now rumbles when your ship is hit (heavier for the hull than the shield), when your shield fails, when the autopilot hands the ship back (no longer when you take it back from keyboard or mouse) and twice when one of the game\'s boxes waits for your answer. Strength under <b>Rumble</b> (<code>rumble</code>, 0 = off); never the only cue; silent while the game is in the background, in menus and cutscenes (paused: only those boxes), and while keyboard and mouse are in use.', 'Hit effects, Options page'],
        ['<b>Controller backend</b> (advanced row, <code>pad_backend</code>): 0 XInput (default, unchanged), 1 SDL3 (experimental) for PlayStation and Switch Pro pads with their own button prompts, and the Xbox pad through SDL; not yet tested with real PlayStation or Switch pads. FLvibed.dll grows by about 1.2 MB.', 'Options page, Controls'],
        ['<b>Torpedoes on RB:</b> holding RB launches the torpedo alone (0.1.0 launched a missile with it); a tap launches the missiles on release.', 'Controls'],
        ['<b>Turret view while the autopilot flies:</b> hold X to look around from the turret camera while the autopilot keeps flying and fighting; the right stick turns the camera and does not take the ship back.', 'Flight &amp; aim, Autopilot'],
        ['<b>Dealers:</b> B with the focus on BUY / SELL or the quantity slider goes back to the selected item instead of closing the dealer (B BACK on the prompt bar).', 'Menus and bases'],
        ['<b>Options page:</b> the stick deadzone setting applies on the page itself too.', 'Options page'],
        ['<b>Options page:</b> a long help text above the page widens to the screen\'s left instead of losing its end (the Rumble row\'s last words were cut at 4:3).', 'Options page'],
        ['The autopilot on the pad is always View held: the unused alternatives (both stick clicks, hold Menu) and their setting <code>autopilot_pad</code> are gone.', 'Controls'],
        ['The main menu, the MULTIPLAYER button\'s LAN / INTERNET prompt and the multiplayer death dialog take the pad\'s presses directly on the game\'s own buttons (no simulated mouse click); the pad keeps working inside the game\'s own dialog loops (connection errors), which used to freeze it.', 'Not implemented yet (Controller UI)'],
        ['On the multiplayer LAN / INTERNET question the D-pad keeps the focus on its answers (it could walk onto the main menu\'s buttons behind, where A did nothing).', 'Not implemented yet (Controller UI)'],
        ['<b>The pad in the background:</b> while another window is in front the controller is ignored in menus and flight alike and does not vibrate; <b>Controller only while the game is in focus</b> (<code>focus_only</code>, on) decides for both (0.1.0: menus always, flight only with the setting). A button held when you come back is ignored until you let go.', 'Options page'],
        ['The chat never shows an unfilled name template ("%s0 %s1 %s2 %d0").', ''],
        ['<b>Every feature is on by default:</b> hit effects at the screen edges, the crosshair pulses, the autopilot\'s prompts for new players and the red marker before a hostile speaker\'s name. Each can be turned off in its own row.', 'Hit effects, Autopilot, Subtitles &amp; movies'],
      ] },
      { t: 'table', title: 'The Advanced Autopilot', head: ['Change', 'Where'], rows: [
        ['<b>Travel by the best path:</b> a plain start on a targeted base, jump gate or jump hole travels there by lanes when they are faster, then docks or jumps (0.1.0 flew a straight line, or did nothing at a far gate).', 'Autopilot'],
        ['<b>All guns on stations and generators:</b> every gun that can reach fires, also while circling with the nose elsewhere; it holds far enough off that every gun can point; a friendly behind a generator no longer stops the guns, and friendlies near the line of fire hold them less often.', 'Autopilot (Weapons)'],
        ['<b>Time on target:</b> it finishes the enemy it is on, flies head-on passes (reverse, turn ahead, slide wide, keep firing while the shield lasts), keeps a distance a crossing enemy cannot outturn and learns the best one per pair of ships, leads its missiles, fires every launcher at big targets as it reloads; its fight odds count the shield damage it deals.', 'Autopilot (Time on target)'],
        ['<b>It rolls and flies level:</b> rolls toward more guns on target, barrel-rolls with a dodge when no gun loses, levels the ship on straight flights, steers true while rolled.', 'Autopilot'],
        ['<b>Following, holding, docking:</b> it keeps the follow position itself when the game keeps ending a follow (no blinking free-flight button), steers round what is in the way and keeps out of a planet\'s danger zone, rests behind a stopped leader; a follow or a Hold you started defends itself; it no longer bursts its own missiles on itself, lines a dropped dock at a moving ship up again and brakes into a station\'s bay instead of ramming it.', 'Autopilot (Flight manners)'],
        ['<b>Escapes and huge targets:</b> in an escape mission it pursues nothing before the first jump out, fights only what shoots at it and waits by the next place; in speedrun mode it heads for the next objective while the story still talks; at the Dyson city\'s generators it coasts in from cruise firing its missiles and torpedoes and fights at weapons range.', 'Autopilot (Escapes and huge targets)'],
        ['<b>Loading a save mid-session</b> no longer leaves the autopilot with the previous mission\'s goal, title or mission markers: it starts from the loaded save\'s own.', 'Autopilot (Hand-off)'],
      ] },
      { t: 'table', title: 'Multiplayer (new)', head: ['Change', 'Where'], rows: [
        ['<b>FLvibed works in multiplayer</b> (tested on local HD Edition and vanilla 1.1 servers): HUD 2, targeting, the subtitles\' speaker names, the docked strip, your own name on your comm lines, job-board missions with HUD 2\'s objective line and the autopilot\'s objective mode. Missions, splits and speedrun mode stay single player.', 'Install (Compatibility), Not implemented yet (Multiplayer)'],
        ['<b>The server decides what the autopilot may do:</b> a server line <code>[flvibed autopilot=on]</code>, <code>=travel</code> or <code>=off</code>; on a server that says nothing the setting <code>mp_autopilot</code> (default: travel only). Another player typing the tag cannot change it. For hosts: the FLHook plugin <code>flvibed_server.dll</code>.', 'Not implemented yet (Multiplayer)'],
        ['<b>Survival first on a server:</b> a player who attacks you counts as a threat; the autopilot leaves a lost fight sooner (<code>mp_caution</code>, <code>mp_flee</code>: below 40 % hull). Experimental and off: <code>pvp_duel</code>.', 'Not implemented yet (Multiplayer)'],
        ['The pad on the server and character lists (D-pad to pick, A connect / load, Y new character); vanilla 1.1 lists LAN servers by IPv4, so connecting works; a job\'s marked cargo pods no longer read as hostile ships.', 'Not implemented yet (Multiplayer)'],
      ] },
      { t: 'table', title: 'Subtitles and movies', head: ['Change', 'Where'], rows: [
        ['<b>The 19 scene mixes are subtitled</b> (room scenes recorded as one track: the landing at Manhattan, Lonnigan on the pad, Tekagi\'s garden, ...), with speaker names and word-timed pages; a skipped scene\'s lines leave with it. New data file <code>FLSubtitles\\mixes.tsv</code>.', 'Subtitles &amp; movies'],
        ['The HD Edition intro subtitles the launch radio exchange before "The war had been raging" (five lines added, two completed).', 'Subtitles &amp; movies'],
        ['With mods: a scene whose recording a mod replaced (as Crossfire does) no longer shows the original scene\'s lines; subtitle data saved with a byte-order mark loads.', 'Subtitles &amp; movies'],
      ] },
      { t: 'table', title: 'Compatibility and stability', head: ['Change', 'Where'], rows: [
        ['<b>The original Freelancer 1.1:</b> FLvibed reads its binary data files, so the autopilot knows each system\'s minefields, damaging fields, lethal planet and sun cores and dock rings there too, and the rest of the game data FLvibed reads comes from them as well: HUD 2\'s zone and lane names, prices, pilots, NPC ships, loot and tractor reach, shield thresholds, the bar characters (0.1.0 read HD Edition\'s text files only). HD Edition: unchanged.', 'Install'],
        ['<b>Windows 7:</b> FLvibed.dll no longer imports a Windows 10 function (it did not load there without an extension such as VxKex), and it stays loaded until the game ends (a reported crash on exit). Every release is checked to import nothing newer than Windows 7; the installer declares Windows 7 to 11. Not yet played on Windows 7.', 'Install'],
        ['<b>Game freezes:</b> the game could stop drawing for seconds to minutes (its message loop waited for a message that never came); FLvibed keeps it running (<code>pump_no_block</code>).', ''],
        ['An error inside FLvibed\'s controller logic also releases the pad\'s steering and held buttons; a settings file with an unreadable value keeps the previous value.', ''],
      ] },
      { t: 'table', title: 'Installer and licence', head: ['Change', 'Where'], rows: [
        ['<b>Licence:</b> FLvibed\'s source code is now licensed GPL-3.0, like the subtitle data (README "Credits and licences"; SDL3 for the experimental backend under its zlib licence).', 'Install (Download)'],
        ['The uninstall also removes the motion trace and the speedrun bests file (kept with the settings on request); a hand-written <code>.\\FLvibed.dll</code> line in dacom.ini is recognised.', 'Install'],
      ] },
      { t: 'dev', html: `<p><b>Source:</b> <code>CHANGELOG.md</code> "0.2.0" (every user-visible change since the 0.1.0 release = tag <code>v0.1.0</code>, dev commit <code>864cefe</code>), checked against the development history since that tag. A change that lands adds its line to the changelog and to this section, and a <code>UP()</code> tag in the section that describes it (<code>part2b_doc.js</code>); a release empties this section and drops the tags.</p>` },
    ] },

  { id: 'install', nav: 'Install', title: 'Install, requirements and compatibility',
    lead: `What you need, how FLvibed gets into the game, and what it has been tested with. FLvibed runs on <b>Freelancer: HD Edition 0.7.1</b> (the tested base) and on the <b>original Freelancer 1.1 with a decrypted Freelancer.exe</b> (verified in game through the first mission, M01a). Each line says whether it is verified and where that comes from. FLvibed 0.2.7 (released 4 Nov 2026; the first release, 0.1.0, came out on 26 Oct 2026) comes with a player installer; the steps below are what it does, and how to do the same by hand.`,
    dv: { same: 'Installation and compatibility do not depend on the device; the controller lines below cover the pads.' },
    blocks: [
      { t: 'table', title: 'Requirements', head: ['Item', 'What is needed', 'State and source'], rows: [
        ['<b>The game</b>', 'Freelancer: HD Edition <b>0.7.1</b> (the released version) is the base FLvibed is built and tested on; the original Freelancer 1.1 runs it too (below). The current HDE repository (after 0.7.1) is the second target: its Freelancer.exe edits touch no address FLvibed uses.', OK('HDE 0.7.1') + ' every test install. ' + WIP('HDE after 0.7.1') + ' checked by reading the exe and patches (<code>docs\\HDE_UPSTREAM.md</code>); a second install (FLSharp 0.9.2) for compatibility sweeps, not swept yet'],
        ['<b>A decrypted Freelancer.exe of the 1.1 build</b>', 'Required on any install. The CD\'s Freelancer.exe is SafeDisc-protected (its code is encrypted on disk, so none of FLvibed\'s symbols can be verified in it) and SafeDisc does not run on Windows 10 / 11 at all. HDE 0.7.1\'s exe is the same build (link timestamp 0x3E401B79, same 1,812 KB code section), decrypted.', OK('HDE provides it') + ' (<code>docs\\MOD_COMPATIBILITY.md</code> "The vanilla game\'s Freelancer.exe"); ' + OK('a decrypted vanilla 1.1 exe') + ' in game; other community unprotected 1.1 programs likely qualify'],
        ['<b>Vanilla Freelancer 1.1 runs FLvibed</b>', 'The original game with the official 1.1 patch and a decrypted Freelancer.exe runs the whole mod: all <b>202 / 202</b> of FLvibed\'s signatures resolve on it, as on HDE 0.7.1 and the current HDE repository (one code path on every exe). Tested in game: New Game through M01a ("Mission Result: Success") with rooms on the pad, both HUD styles and both screen styles, HUD 2 with its own-ship and target views, the comm portrait, base, space and movie subtitles, the autopilot, the pause menu and the options page. HDE\'s HudStatus.dll is <b>no longer needed</b> for the own-ship view (FLvibed drives the status panel\'s own 3D view itself). Without HDE: no zone arrival lines in HUD 2\'s place line (HDE\'s Territory.dll / Zone.dll) and the classic HUD\'s maneuver bar does not move for the subtitles\' top panel (HDE\'s HudShift).', OK('vanilla 1.1, in game through M01a') + ' (<code>docs\\MOD_COMPATIBILITY.md</code> "In-game test on vanilla 1.1", commit 0d0bcb7 and the FIX-VIEWS / FIX-TEXT tracks; <code>sigtool check --scan</code>: then 194 / 194; 26 Oct 2026 202 / 202 on HDE 0.7.1, upstream HDE, vanilla and Discovery\'s exe, 202 resolved at run time on HDE and vanilla); ' + NO('vanilla beyond M01a')],
        ['<b>The CD\'s own Freelancer.exe (SafeDisc)</b>', 'Does not start on Windows 10 / 11; its encrypted code resolves 0 of FLvibed\'s symbols statically. (1.0 and 1.1 share this one program: the official 1.1 patch replaces no Freelancer.exe.)', '<span class="st no">not supported</span> (sigtool, <code>docs\\MOD_COMPATIBILITY.md</code>)'],
        ['<b>The 1.1 patch\'s own game DLLs</b>', 'The official 1.1 patch replaces Common.dll, Server.dll, Content.dll, RemoteClient.dll, DALib.dll and FLServer.exe; HDE ships its own builds of Common / Server / Content / DALib. FLvibed reaches those DLLs by their exports and import tables, not by signatures, and works on both: the vanilla test ran on the patch\'s own builds.', OK('through M01a') + ' (<code>docs\\MOD_COMPATIBILITY.md</code>)'],
        ['<b>The fonts</b>', 'FLvibed draws its text in the game\'s own faces, named in <code>DATA\\FONTS\\fonts.ini</code> (Agency FB for labels): from the game\'s <code>DATA\\FONTS</code> files (HDE ships them), else the same face installed in Windows (the official installer puts Agency FB into Windows\\Fonts), else Segoe UI. One log line names the source.', OK('HDE: the game\'s files; vanilla: Windows\' Agency FB') + ' (<code>core\\game\\gamefont.cpp</code>, FIX-TEXT)'],
        ['<b>Other mods or tools you must have</b>', 'None: HD Edition 0.7.1, or vanilla 1.1 with a decrypted exe (above). FLvibed loads through the game\'s own plugin list (<code>EXE\\dacom.ini</code> [Libraries]); no loader, no launcher, no d3d8to9 / DxWrapper (it hooks the game\'s own Direct3D 8).', OK() + ' <code>tools\\deploy.ps1</code>, the vanilla test install'],
        ['<b>Windows</b>', 'Windows 10 or 11. ' + UP() + ' Windows 7 SP1, 8 and 8.1: FLvibed imports nothing newer than Windows 7 (checked on every release: <code>tools\\win7_check.ps1</code>; 0.1.0 imported a Windows 10 function and did not load on Windows 7), and its newer-Windows calls have fallbacks: XInput from <code>xinput9_1_0</code> when <code>xinput1_4</code> / <code>xinput1_3</code> are missing, DPI readout without <code>GetDpiForWindow</code>, movie-line pacing without DWM (Aero off).', OK('Windows 10 / 11') + ' ' + OK('the fallbacks on Windows 11 with FLVIBED_SIM_WIN7, 29 Oct 2026: intro lines, xinput9_1_0 loaded, the winmode readout') + ' ' + NO('in game on Windows 7; a real pad read through xinput9_1_0')],
        ['<b>Runtime prerequisites</b>', 'Windows and the game. One DLL with the C runtime built in: no Visual C++ redistributable.', OK() + ' <code>build.cmd</code> (/MT)'],
        ['<b>Shipped data files</b>', '<code>EXE\\FLSubtitles\\</code>: subtitles.tsv, movies.tsv, mixes.tsv, movie_frames.tsv, speaker_colors.tsv, word_times.tsv (the subtitle text and timing; no game audio). <code>EXE\\FLvibed\\autopilot.3db</code> (the maneuver bar\'s autopilot icon; without it an overlay glyph is drawn).', OK() + ' <code>tools\\deploy.ps1</code>'],
        ['<b>Optional</b>', 'The full original intro from the Bonus DVD (<code>movie_intro</code> offers only the files present). Never shipped.', OK()],
      ] },
      { t: 'table', title: 'Install, update, uninstall', head: ['Step', 'What happens', 'State'], rows: [
        ['<b>On vanilla Freelancer</b>', '1. Install the game with its official installer (you accept the EULA there; it also installs the Agency FB fonts and the registry keys). 2. Apply the official 1.1 patch. 3. Replace <code>EXE\\Freelancer.exe</code> with a decrypted 1.1 program (SafeDisc does not run on Windows 10 / 11). 4. Install FLvibed as below: <code>FLvibed.dll</code>, the dacom.ini line, <code>FLvibed.ini</code> and the data files.', OK('the vanilla test install') + ' (<code>docs\\MOD_COMPATIBILITY.md</code>: its test-only additions - flplusplus for saving in the game folder, a windowed byte patch - are not player requirements)'],
        ['<b>On HD Edition</b>', '1. Install Freelancer: HD Edition 0.7.1 with its installer (it brings the decrypted exe, its plugins and the fonts). 2. Install FLvibed as below.', OK('every test install')],
        ['<b>Install FLvibed</b>', 'Copy <code>FLvibed.dll</code> into <code>EXE\\</code>, add the line <code>FLvibed.dll</code> to <code>EXE\\dacom.ini</code> [Libraries] after the game\'s own plugins (on vanilla after <code>.\\flmaterials.dll</code>; with FLUF above or below its <code>fluf/FLUF.dll</code> line, see Compatibility), copy the data files above (<code>EXE\\FLSubtitles\\*.tsv</code>, <code>EXE\\FLvibed\\autopilot.3db</code>), write <code>EXE\\FLvibed.ini</code> ([Modules]: <code>subtitles = 1</code>, <code>controller = 1</code>). No game file is changed. <b>The one-click way:</b> <code>FLvibed-0.2.7-Setup.exe</code> does all of this - it finds the game (HD Edition\'s installer entry, the original game\'s registry key, the default folders, its own folder, else a folder picker), keeps an existing FLvibed.ini, backs up dacom.ini once, leaves an uninstaller in <code>EXE\\FLvibed\\</code> and an entry in Windows\' installed apps; no administrator rights unless the folder is protected (then it asks). Unsigned: SmartScreen may warn.', OK('release 0.1') + ' setup: 84 automated checks on copies of the HDE and vanilla dacom.ini, an HDE test install installed by it and played to the main menu; the zip by hand (its README.txt)'],
        ['<b>Download</b>', 'The project\'s GitHub releases page, two files: <b>FLvibed-0.2.7-Setup.exe</b> (the installer / uninstaller) and <b>FLvibed-0.2.7.zip</b> (to install by hand: <code>EXE\\FLvibed.dll</code> - version 0.2.7 in its file properties, the logs and the options page\'s About - <code>EXE\\FLvibed.ini</code>, <code>EXE\\FLSubtitles\\*.tsv</code>, <code>EXE\\FLvibed\\autopilot.3db</code>, README.txt, CHANGELOG.md, LICENSES with GPL-3.0 for the subtitle data). Both from <code>tools\\package.ps1</code>. ' + UP() + ' The code is licensed GPL-3.0 too; LICENSES also holds SDL3\'s zlib licence (the experimental <code>pad_backend</code> 1).', OK('0.1.0, 26 Oct 2026; 0.2.0, 1 Nov 2026')],
        ['<b>Update</b>', 'Run the new version\'s setup (or merge the new zip\'s EXE folder over the old files); the settings files stay. ' + UP() + ' Updating from 0.1.0: the first start of 0.2.0 resets every FLvibed setting to its default (the old files kept as <code>&lt;name&gt;.before-0.2.0</code>; the per-save modes and speedrun bests stay).', OK('unit-tested')],
        ['<b>Uninstall</b>', 'Windows Settings &gt; Apps &gt; Installed apps &gt; FLvibed, or the setup\'s Uninstall: FLvibed\'s dacom.ini line out, FLvibed.dll, the data and the logs deleted; the player chooses whether FLvibed.ini, FLController.ini, FLSubtitles.ini and the per-save modes (<code>EXE\\FLvibed\\saves.ini</code>) go too. Saves stay valid. By hand: the same files and the dacom.ini line. ' + UP() + ' The motion trace and the speedrun bests file go with the data (kept with the settings on request); a hand-written <code>.\\FLvibed.dll</code> line in dacom.ini is recognised.', OK('setup, tested') + ' dacom.ini comes back byte for byte'],
        ['<b>Settings</b>', 'In game: Options &gt; FLVIBED (and the pause menu\'s FLVIBED button). Files: <code>EXE\\FLvibed.ini</code> (modules), <code>EXE\\FLController.ini</code> [Controller] / [Autopilot], <code>EXE\\FLSubtitles.ini</code> [Subtitles].', OK()],
        ['<b>Switch things off</b>', 'A whole module: GENERAL &gt; MODULES (takes effect after a restart). Each feature: its own row (HUD, cues, subtitles channels, movies, autopilot ...).', OK()],
      ] },
      { t: 'table', title: 'Compatibility', head: ['With', 'What to expect', 'State and source'], rows: [
        ['<b>HDE 0.7.1\'s plugins</b>', 'jflp, console, HudShift, HUDless, MP3codec, MPRep, numeric, ranks, storyfactions, Territory, TurretZoom, WheelScroll, Zone, Hail, MultiIntro, callsign, flplusplus, FLSharp, HudFacility / HudWeaponGroups / HudTarget / HudStatus, DelayDisplay, gls_workaround: FLvibed\'s hooks chain behind theirs.', OK() + ' all test installs run them (<code>docs\\MOD_COMPATIBILITY.md</code>)'],
        ['<b>FLSharp 0.9.2 (newer HDE)</b>', 'Known overlaps to check: its Options-screen hooks, the cursor-shown flag, an extra maneuver-bar layout call.', NO() + ' (<code>docs\\research\\</code> FLSharp note)'],
        ['<b>FLUF</b> (The Starport\'s framework, actively developed: nightly builds, stable 2.0.0)', 'Not on HD Edition: FLUF refuses to load beside HDE\'s jflp, FLSharp, DelayDisplay, MP3codec, storyfactions and callsign. On vanilla 1.1 or a FLUF-based mod <b>both run whichever of the two lines comes first in dacom.ini</b>. Tested build: FLUF nightly-2026-10-16-03-03. What FLvibed does beside FLUF (its windows on top, the palette taking the keys, the controller on its windows, one cursor) and the recorded conflicts: the section <b>With FLUF</b>.', OK('verified in game beside the nightly in both load orders, vanilla 1.1; regression pass 26 Oct 2026') + ' ' + WIP('FLUF itself needs a fix to start on unmodified game data (its universe cache)') + ' ' + NO('FLUF modules beyond its debugger; other FLUF builds = co-residency only') + ' (<code>docs\\MOD_COMPATIBILITY.md</code> FLUF, <code>docs\\research\\fluf.md</code>)'],
        ['<b>Discovery, Crossfire</b>', 'Different patched exes / plugin stacks (Discovery patches Freelancer.exe and Content.dll on disk and runs an older FLUF); a moved address fails closed, a feature may be off.', NO() + ' (<code>docs\\research\\discovery.md</code>, <code>crossfire.md</code>)'],
        ['<b>Gameplay plugins</b>', 'StoryLvl, Lane Speed, Moors, Equip Mass and others: the autopilot reads what they change at run time.', OK('partly') + ' (<code>docs\\MOD_COMPATIBILITY.md</code>)'],
        ['<b>Multiplayer</b> ' + UP(), 'Works: where the game\'s single-player server has no world (every multiplayer client loads Server.dll empty), FLvibed reads the client\'s own data - positions, attitudes, pilot names, factions, shields, lanes, credits - so the pad, HUD 2, targeting, the subtitles\' names and the Advanced Autopilot work as in single player. <b>The autopilot follows the server:</b> a server line <code>[flvibed autopilot=on]</code>, <code>=travel</code> (flying and docking, no shooting) or <code>=off</code> decides, else the setting <code>mp_autopilot</code> (Autopilot ini; default 1 = travel only, by design). The story\'s missions, splits / speedrun mode and the New Game prompt stay single player. Details <code>docs\\MULTIPLAYER.md</code>.', OK('local HDE 0.7.1 server with FLHook, 28 Oct 2026: HUD 2 on the pad, targeting data, comms and names, the autopilot docking under fire and on a 49 km trip, the server\'s permission line, quitting (dev and release)') + ' ' + OK('two clients on one server with autopilot-led PvP, 28 Oct 2026') + ' ' + OK('vanilla 1.1 client on a vanilla 1.1 server, 28 Oct 2026 (job, docked strip, names)') + ' ' + NO('internet and modded servers')],
        ['<b>Resolutions, aspect ratios, DPI</b>', 'Borderless 3840x2160 (the main mode), windowed 1600x1200 (4:3) and 2560x1080 (21:9), borderless 1280x720, a DPI-unaware game process.', OK() + ' display matrix, 21 and 25 Oct 2026 (<code>docs\\kb\\display.md</code>)'],
        ['<b>Borderless windowed by FLvibed</b>', 'Where nothing else provides it (option <code>borderless</code>, default Auto): the original game alone or with FLUF runs as a window without frame covering its monitor at the monitor\'s resolution, never exclusive fullscreen; FLUF\'s Alt+Enter switches it with a bordered window. HD Edition provides its own (its exe and its Direct3D wrapper): FLvibed stays out (Always forces FLvibed\'s over it). Sharp at high DPI only with a DPI-aware exe: the game creates its window before any plugin loads, so FLvibed cannot make it DPI-aware; a DPI-unaware game covers the monitor at its logical size, stretched by Windows. In any borderless window that covers its monitor (FLvibed\'s, HDE\'s, a wrapper\'s) the mouse stays in the game at the screen edges, as in exclusive fullscreen (the game keeps it only when its fullscreen flag is set; FLvibed sets the mouse\'s edge clamp while the window covers the monitor).', OK('vanilla 1.1 alone and with FLUF in both orders, DPI-aware and unaware; HDE stays out') + ' ' + OK('the mouse at the screen edges: tested by hand on HDE 0.7.1 borderless, 26 Oct 2026') + ' ' + NO('by the player: Alt+Tab, Alt+Enter, a vanilla start configured for fullscreen')],
        ['<b>Exclusive fullscreen</b>', 'Expected to work; it takes the screen, so it has not been run in the automated tests.', NO()],
        ['<b>Movies</b>', 'Fit and subtitled intros, the same path on HDE and vanilla.', OK('HDE 3840x2160 borderless, HDE 1600x1200 windowed, vanilla 1280x960 windowed') + ' ' + NO('exclusive fullscreen')],
        ['<b>Recording and streaming</b>', 'The movie subtitles are drawn in a child window of the game window: window capture and display capture (and the taskbar preview) show them. <b>OBS Game Capture does not</b>: the game\'s movies play outside its Direct3D output, so Game Capture misses the video itself too. Everything else FLvibed draws is in the game\'s own frame.', OK('window capture, PrintWindow, taskbar preview') + ' ' + NO('OBS itself, not tested')],
        ['<b>Controllers</b>', 'XInput pads (Xbox). PlayStation and Nintendo pads work through an XInput layer (Steam Input, DS4Windows ...); their glyphs follow the pad\'s HID vendor id or your choice.', OK('virtual pad, all screens; real Elite Series 2: flight and combat') + ' ' + NO('real pad in menus and bases; Sony / Nintendo hardware')],
      ] },
      { t: 'settings', title: 'Module switches (GENERAL)', keys: ['mod_subtitles', 'mod_controller'] },
      { t: 'settings', title: 'Window mode (CONTROLLER > SYSTEM; read at the game\'s start)', keys: ['borderless'] },
      { t: 'dev', html: `<p><b>Loading:</b> <code>tools\\deploy.ps1</code> writes <code>dacom.ini</code> [Libraries] with <code>FLvibed.dll</code> once, after the game's own plugins (the old per-module DLLs removed), <code>FLvibed.ini</code> [Modules], copies <code>subtitles\\data\\*.tsv</code> to <code>EXE\\FLSubtitles\\</code> and <code>controller\\data\\autopilot.3db</code> to <code>EXE\\FLvibed\\</code>. It refuses to start a game that would write the shared <code>Documents\\My Games\\Freelancer</code> (test installs keep their own data).</p>
<p><b>Signatures:</b> each module part resolves <code>core\\flexe.h</code> once (~0.1 ms fast path at the v1.1 address; a detour JMP from another plugin counts as matching; otherwise a <code>.text</code> search that must match exactly once); an unresolved symbol refuses only its hook / call / read and is logged. Every symbol resolves on HDE 0.7.1, the HDE repository's exe and a decrypted vanilla 1.1: 202 / 202 (26 Oct 2026, the static check over <code>core\\flexe.h</code>, also Discovery's exe; earlier <code>sigtool check --scan</code>, also <code>--shift 16 --hooked</code>; no signature spans the filler bytes between functions, where the cracked vanilla exe keeps leftover call bytes); in game on vanilla all resolve at run time (194 then, 202 in the 26 Oct regression pass), nothing refused but the maneuver bar shift (HudShift is HDE's); TextCtlSetProperty, flagged "verify in game", showed the texts normally. On the SafeDisc CD exe <code>sigtool</code> resolves 0 statically (encrypted <code>.text</code>; <code>docs\\MOD_COMPATIBILITY.md</code>). Server.dll / Content.dll reads are found by pattern (<code>controller\\src\\host\\events.cpp</code>) and fail closed the same way.</p>
<p><b>HDE plugin dependencies left:</b> HUD 2's place line shows the game's arrival line, which HDE's <code>Territory.dll</code> (system houses) and <code>Zone.dll</code> (zone edges) feed; the subtitles' maneuver-bar shift works on HudShift's relocated constants (vanilla: refused, the bar stays). Gone (FIX-VIEWS, 25 Oct 2026): the own-ship view no longer needs <code>HudStatus.dll</code> - the status panel's own 3D view is drawn through the panel base's routines in HudStatus's order (six signed symbols); the target view sets its view mode for the draw; the flat icons read any square sheet (vanilla's 256 px <code>ButtonTextures.txm</code>); the comm portrait stays with its line on every HUD (HUD 2's 4:3 panel above the line; vanilla's classic HUD beside its line's box: no HudShift needed). <b>Fonts</b>: <code>core\\game\\gamefont</code> reads fonts.ini as text (HDE) or BINI (vanilla), faces from <code>[TrueType]</code>, files from <code>[FontFiles]</code>, else Windows' installed face, else Segoe UI. <b>Game data</b> (29 Oct 2026) ${UP()}:every reader of the game's inis goes through <code>core\\game\\ini</code>, text (HDE) or BINI (vanilla) - so on vanilla 1.1 the autopilot knows each system's minefields, damaging fields, lethal planet / sun cores and planet dock rings, and HUD 2 the zone and lane names (before: HDE only; the HDE tables proven identical by <code>tests\\universe_test.cpp</code>; the universe tables seen in game on vanilla 1.1, 29 Oct 2026, with an M01a leg on it). <b>Movies</b>: Movie.dll plays through the VMR-7 in its own child window while the game's Present stops; the subtitles live in a child window above it (OBS Game Capture sees nothing of the movie). Open: vanilla beyond M01a, the FLSharp 0.9.2 sweep. Release: <code>tools\\package.ps1</code> (the zip and the setup), <code>tools\\setup\\</code>.</p>` },
    ] },

  { id: 'fluf', nav: 'With FLUF', title: 'With FLUF: what FLvibed does beside it',
    lead: `<b>FLUF</b> (the Freelancer Universal Framework by The Starport) adds its own windows to the game: a command palette, an options / player-status window, its own nav map, notifications and a Debug Window. FLvibed knows them and steps around them: <b>FLUF's windows always stay on top</b>; FLvibed's HUD parts fade under the one that covers them (each part on its own, nothing moves), its prompts and subtitles step aside, the controller drives FLUF's windows, and an open palette takes all keyboard input like a chat box. FLUF runs only on the <b>original Freelancer 1.1</b> (or a FLUF-based mod), never on HD Edition (it refuses HDE's plugins). Tested build: <b>FLUF nightly-2026-10-16-03-03</b>, in both load orders.`,
    dv: { pad: 'With the controller: the left stick moves FLUF\'s arrow, A clicks, B closes the window you are in; on the palette the D-pad steps its list and A runs the command.', km: 'With keyboard and mouse FLUF works as FLUF ships it; FLvibed only holds its own keys (the autopilot key, the page\'s keys) while the palette is open.' },
    blocks: [
      { t: 'table', title: 'What FLvibed does beside FLUF', head: ['Part', 'What happens', 'State'], rows: [
        ['<b>Install</b>', 'Add <code>FLvibed.dll</code> to <code>EXE\\dacom.ini</code> [Libraries] above or below <code>fluf/FLUF.dll</code> (FLUF\'s docs put FLUF last; FLUF_boot works too). Both run in either order: FLvibed hooks FLUF\'s own handlers instead of fighting over the game\'s functions.', OK('both orders and FLUF_boot, vanilla 1.1')],
        ['<b>Detection</b>', 'FLvibed recognises the FLUF build once at start. The tested nightly: full awareness (its windows read live from FLUF\'s interface state). Any other build (stable 2.0.0, a later nightly, Discovery\'s): <b>co-residency only</b> - FLvibed runs as without FLUF and writes one log line; nothing is guessed.', OK('nightly-2026-10-16') + ' ' + NO('other builds (fail closed by design)')],
        ['<b>FLUF\'s windows on top</b>', 'HUD 2\'s parts, its menu strip and card, the prompt pills and the subtitles keep out of every open FLUF window: the HUD parts under it fade to 15 % (each on its own, never moved), the pills and the subtitle block move clear. The setting <b>FLUF windows</b> picks which windows count.', OK('both orders, HUD 2 and classic')],
        ['<b>The command palette takes the keys</b>', 'While FLUF\'s palette is open - its search box focused or not - FLvibed holds all of its own keyboard input (the autopilot key, the options page\'s keys) and every key goes to FLUF, like an open chat box. FLUF does not focus the search box when it opens: click it (or the pad cursor + A) before typing.', OK('hands-on, order A') + ' ' + NO('hands-on, order B')],
        ['<b>The controller on FLUF\'s windows</b>', 'On any FLUF window that takes input (palette, options, map, a palette command\'s window, module windows): left stick = FLUF\'s arrow, A / X = the mouse buttons, right stick = the wheel, B closes the focused window (palette: the first B clears the text, the second closes; a command\'s window by its close button). On the palette the D-pad steps the list and A runs the command; the prompt bar says so. The B or A that closed a window never reaches the ship (no free-flight tap after a close).', OK('both orders; command windows and the press rule in the hands-on run')],
        ['<b>One cursor</b>', 'FLUF draws its own arrow at the game\'s cursor position; the pad moves that position, FLvibed draws no second arrow, and the pad screens\' hidden cursor hides FLUF\'s too.', OK()],
        ['<b>Keys FLUF claims</b>', 'Its palette and options keys (unbound until you bind them), Escape while one of its windows is open, the mouse over its windows, the nav map key (FLUF\'s map; the pad drives it). If you bind FLUF\'s palette or options key to FLvibed\'s autopilot key, both fire: rebind one (<code>autopilot_key</code> on the options page).', OK('documented')],
        ['<b>The autopilot\'s evasion</b>', 'FLUF owns the game\'s Evade behaviour; FLvibed leaves it alone (one log line) and the autopilot dodges with its own slide bursts.', OK()],
        ['<b>The options page</b>', 'The FLUF windows row says NO FLUF INSTALLED, FLUF DETECTED or FLUF DETECTED - CO-RESIDENCY ONLY.', OK()],
        ['<b>Borderless window</b>', 'The original game has no borderless mode and FLUF adds none; FLvibed\'s <code>borderless</code> (Auto) makes it borderless, so FLUF\'s Alt+Enter switches between FLvibed\'s borderless window and the game\'s bordered one (never exclusive fullscreen).', OK('both orders, by the same call FLUF makes') + ' ' + NO('the player pressing Alt+Enter / Alt+Tab')],
      ] },
      { t: 'table', title: 'Recorded conflicts (FLUF\'s, not FLvibed\'s)', head: ['What you see', 'Why', 'State'], rows: [
        ['An endless chain of "ERROR ... [system] value pos missing parameter 2" boxes at the first start on the game\'s own data; the menu never comes.', 'FLUF\'s universe cache reads the game\'s two-value positions and one-value zone sizes as three-value vectors. Not in FLUF\'s issue tracker as far as we know. The tests ran on a test-only copy of the universe files with padded values, never shipped.', WIP('FLUF bug, recorded')],
        ['The first run sets the resolution to the screen size; on a high-DPI screen a DPI-unaware game gets the logical size (1920x1080 on 4K at 200 %), stretched by Windows.', 'FLUF issue #111 and the game\'s DPI-unawareness (a DPI-aware exe renders sharp at the physical size).', WIP('recorded')],
        ['Exclusive fullscreen by FLUF\'s Alt+Enter froze the game (without FLvibed\'s borderless window).', 'The Direct3D 8 device reset fails while the device is lost and the original game never retries. FLvibed now releases everything before a reset; with <code>borderless</code> Auto the toggle never reaches exclusive fullscreen.', NO('FLUF alone with Alt+Enter, hands-on')],
        ['The chase camera follows more loosely (the ship leaves the frame in hard turns); in-engine scenes look zoomed at high resolutions; changing the resolution in FLUF\'s options window may crash.', 'FLUF\'s camera fixes and its open issue #111.', WIP('FLUF\'s')],
      ] },
      { t: 'settings', title: 'Setting (CONTROLLER > SYSTEM)', keys: ['fluf_windows'] },
      { t: 'dev', html: `<p><b>Detect</b> (<code>core\\fluf.*</code>, served to both logics by the HUD bus): FLUF.dll's PE timestamp + image size (its version resource is always 1.0.0) - nightly-2026-10-16 = aware; then FLUF's exported Dear ImGui (version "1.92.7 WIP"), the context, the IO and the window list with offsets measured on FLUF's headers, every region tied to the exports first; one failed check = co-residency only for good. Once per FLUF frame: each open top-level window by kind (palette, options / status, map, developer, toast, other), its rectangle, FLUF's click rule, <code>WantTextInput</code>, ImGui's focused window. <b>Hooks</b>: FLUF's six restore-style detours (frame update, UI render, cursor, WinKey, HandleKey, PlayArch) are hooked at FLUF's handler in either order (<code>hk::AdoptRestoreStyle</code>); what FLUF patched at run time (control setters, server slots, Common.dll vtables, the lane law) is read back from the game module's original image (<code>hk::OriginalAt</code> / <code>VtableSlot</code>). <b>Input</b>: <code>core\\fluf_rules.h</code> (palette open = hold every FLvibed key), <code>core\\press_gate.h</code> (a press belongs to the pad consumer that had the pad when it went down). Unit tests <code>fluf_hooks</code>, <code>fluf_probe</code>, <code>orig_image</code>, <code>press_gate</code>. Evidence and the per-item table: <code>docs\\MOD_COMPATIBILITY.md</code> FLUF, <code>docs\\research\\fluf.md</code> "FLUF in play" (incl. FLUF's known issues).</p>` },
    ] },

  { id: 'aim', nav: 'Flight & aim', title: 'Flight and aim with the controller',
    lead: `Freelancer's guns fire where the cursor points, not along the nose. On the pad FLvibed keeps that: the right stick steers through the game's own mouse-flight steering, the left stick is the throttle and strafe, and the reticle either locks onto your target's lead cross by itself (<b>gimbal aim</b>, the default) or follows the right stick with aim assists (<b>reticle aim</b>). The ship is never steered for you.`,
    dv: { pad: 'Gimbal and reticle aim are the controller\'s.', km: 'With keyboard and mouse you fly and aim with the mouse exactly as in the game; gimbal and reticle aim apply to the controller only. The captures below are the controller\'s.' },
    blocks: [
      { t: 'cmp', title: 'Gimbal vs reticle aim (classic HUD)', cl: CAP('a_reticle_cl'), h2: CAP('a_gimbal_cl'), ll: 'RETICLE AIM', rl: 'GIMBAL AIM', cap: 'The same moment with the right stick pushed up-right and a pirate targeted. Reticle aim: the reticle has moved with the stick. Gimbal aim: the stick only steers; the reticle stays centred and locks onto the selected hostile\'s lead cross whenever it is on screen.' },
      { t: 'cmp', title: 'Gimbal vs reticle aim (HUD 2)', cl: CAP('a_reticle_h2'), h2: CAP('a_gimbal_h2'), ll: 'RETICLE AIM', rl: 'GIMBAL AIM', cap: 'The same on HUD 2: the ring stays round the screen centre; under reticle aim the reticle dot moves off it with the stick.' },
      { t: 'p', html: `<b>Targeting:</b> nothing is picked for you and a target you chose is never changed; the right-stick click (RS) picks the nearest enemy within 10 km (presses within three seconds take the next ones; after a pause it starts again from the nearest), and with no enemy near the nearest object inside HUD 2's reticle ring, else the game's nearest enemy (a double click clears it; [RS] x2 CLEAR on the target card); with nothing targeted, firing at a ship selects it (<code>fire_target</code>). LB opens the target picker (threats, mission, navigation, ships, loot; MISSION WAYPOINT = the objective's marker, set as your waypoint when your own list is empty). <b>Turret view</b> (X held toggles it on / off): the reticle stays centred - gimbal lock-on included - and the right stick turns the camera through the game's own look commands. <b>Assists</b> under reticle aim: slowdown, magnetism and a capped rotation assist near a target. <b>Steering</b>: full stick = the ship's top turn rate (<code>steer_scale</code>), a radial curve (<code>steer_expo</code>), dead zones and the throttle rate on the CONTROLLER tab.` },
      { t: 'settings', title: 'Aim and flight settings (CONTROLLER > AIM, STICKS, TARGETING)', keys: ['aim_mode', 'aim_cone', 'aim_smooth', 'invert_y', 'steer_expo', 'steer_scale', 'stick_deadzone', 'trigger_threshold', 'throttle_rate', 'auto_target', 'fire_target', 'rumble'] },
      { t: 'dev', html: `<p><b>How:</b> the host detours the game's mouse-flight steering (<code>exe::MouseSteer</code>) and feeds the stick offset into it for that call only (engage flag restored: no MOUSE FLIGHT label); releasing control sends a few no-turn frames (else the ship keeps spinning). While the pad flies the HUD controls are hidden from the UI hit test (<code>exe::HitTest</code>) so the reticle can cross the HUD. Gimbal: the lead point is the game's own (<code>CShip::get_tgt_lead_fire_pos</code>); hostile = attitude &lt;= -0.55. Code <code>controller\\src\\impl\\controller.cpp</code> (PadAim), <code>aim.cpp</code>; reference <code>controller\\docs\\FLIGHT_AIM.md</code>. Steering scale is measured on the Starflier only (other ships: <code>controller\\CLAUDE.md</code> "Not verified yet"). Captures: <code>research\\experience\\runs\\spec_flvibed_2026-10-25\\aim_*</code>.</p>` },
    ] },

  { id: 'flight', nav: 'Flight HUD 2', title: 'Flight HUD 2',
    lead: `The game's flight HUD fills about a fifth of the screen with boxes. HUD 2 keeps every function but puts each value in one place: the ship's state where your eyes already are (around the reticle), the corners by job, and only the actions that apply right now. It uses Freelancer's own art (its flat icons, brackets, wireframe views, palette and Agency FB) so it still feels like Freelancer.`,
    dv: { pad: 'Captured with the controller (glyph prompts). Choose K&amp;M to see the keyboard form.', km: 'With keyboard and mouse HUD 2 shows too (the default; the HUD row set to Classic keeps the game\'s HUD): keycaps from your key map, clickable chips. The first comparison switches to the keyboard captures; the others were captured with the controller (the same panels, glyphs instead of keycaps).' },
    blocks: [
      { t: 'p', html: `${UP('new in 0.2.0')} <b>The bottom of the screen, rearranged (31 Oct 2026):</b> the lower centre - under the reticle ring, where your own ship flies - is now kept free of HUD 2: only the game's own markers (a target's brackets, the reticle) appear there. The cruise state moved inside the ring (the charge seconds, then CRUISE ON), the action prompts went into two lanes beside the bottom panels (moving and controlling the ship on the left, firing, using and targeting on the right; TRACTOR &lt;item&gt; and TRACTOR ALL n are two of them), and both bottom panels got smaller: the ship panel 0.31 x 0.15 H, the weapons panel 0.40 x 0.15 H with the D-pad cross on its own plate above its right end. A name too long for its room shows its start with "...", waits 1.5 s, then scrolls to its end like a station's display board. The frames below show this layout, captured from the release build.` },
      { t: 'gal', title: 'The layout since 31 Oct 2026 (controller)', items: [
        { img: CAP('m_combat'), title: 'Combat', cap: '[B] REVERSE in the left lane, [X] TURRET in the right; the escorts in the 0.31 H ship panel; a gun group too long for its room shows its start with "..." before it scrolls; the launcher with its count.' },
        { img: CAP('m_travel'), title: 'Calm travel', cap: '[A] DOCK and [Y] CRUISE in the left lane; nothing under the ring. The ship panel: name and class, hold, credits.' },
        { img: CAP('m_cruise'), title: 'Cruise charging', cap: 'The seconds inside the ring where the power arc was (the speed moves up), the bottom arc filling cyan; [Y] CANCEL CRUISE first in the left lane, whole.' },
        { img: CAP('m_dock'), title: 'Docking (autopilot)', cap: 'AUTOPILOT · DOCK FORT BUSH with progress and DOCK REQUESTED in the nav; GOALS and HOLD TAKE CONTROL stacked in the left lane\'s two rows.' },
        { img: CAP('m_lane'), title: 'Trade lane', cap: 'GOALS and HOLD TAKE CONTROL in the left lane; the lower centre empty.' },
      ] },
      { t: 'gal', title: 'The contextual HUD (0.2.5)', items: [
        { img: CAP('k_idle'), title: 'Calm flight: HUD 2 fades out', cap: 'Nothing to report, nothing drawn: the view is yours.' },
        { img: CAP('k_steer'), title: 'Steering: ring and speed return', cap: 'Steering (stick or mouse) brings the reticle ring and the speed back for four seconds.' },
        { img: CAP('k_boost'), title: 'Boost: ring and speed', cap: 'Boosting wakes the ring and speed the same way, then they fade again.' },
        { img: CAP('k_full'), title: 'FULL mode', cap: 'The HUD setting on FULL keeps every part of HUD 2 on screen all the time.' },
      ] },
      { t: 'gal', title: 'Prompts and panels (0.2.5)', items: [
        { img: CAP('k_wrap'), title: 'A long prompt wraps', cap: 'A label too long for its place wraps onto two lines in a slightly smaller font; the whole text is always visible.' },
        { img: CAP('k_lock'), title: 'LOCKED BY THE MISSION', cap: 'Pressing a maneuver the mission has locked shows this at the top instead of doing nothing.' },
        { img: CAP('k_panels'), title: 'Panels sized to their content', cap: 'The target card, contact list, ship panel and loadout panel are only as wide as what they show.' },
      ] },
      { t: 'cmp', title: 'Combat (controller)', cl: CAP('f_combat_cl'), h2: CAP('f_combat_h2'), cap: 'A fight in Bretonia (M05): threat list under the target card, [B] REVERSE and [X] TURRET in the bottom lanes, escorts in the ship panel, the gun groups with the active one marked, the D-pad cross. Left: the classic HUD with the pad badges and the combat legend.',
        km: { title: 'Keyboard and mouse', cl: CAP('f_kbm_cl'), h2: CAP('f_kbm_h2'), cap: 'The keyboard form: the maneuver row under NEURONET as clickable chips with their keys (F2, F3, F4 ...), keycaps instead of glyphs (CTRL+R NEXT ENEMY), the consumables as a 2 x 2 grid of key + slot. Left: the game\'s default HUD.' } },
      { t: 'cmp', title: 'Calm travel', cl: CAP('f_travel_cl'), h2: CAP('f_travel_h2'), cap: 'Calm flight dims the ring to 40 % and the side panels to 60-65 %; [A] DOCK and [Y] CRUISE in the left lane beside the ship panel. The target card shows a friendly station without bars it cannot use, [RS] x2 CLEAR in its footer.' },
      { t: 'cmp', title: 'Cruise charging', cl: CAP('f_cruise_cl'), h2: CAP('f_cruise_h2'), cap: 'The ring\'s bottom arc fills cyan while cruise charges, the seconds inside the ring under the speed; [Y] CANCEL CRUISE in the left lane beside the ship panel. Left: the game\'s own HUD.' },
      { t: 'cmp', title: 'Docking with the autopilot', cl: CAP('f_dock_cl'), h2: CAP('f_dock_h2'), cap: 'The nav top left: AUTOPILOT + DOCK FORT BUSH with progress and DOCK REQUESTED; TAKE CONTROL on the context line (now the left lane). Left: the classic pad layer with a dockable target (DOCK AT FORT BUSH in the legend).' },
      { t: 'gal', title: 'Every other state', items: [
        { img: CAP('f_lane'), title: 'Trade lane', cap: 'The autopilot on the Norfolk Shipyard lane in New York: AUTOPILOT, TRADE LANE NORFOLK SHIPYARD, rings left and ETA with the ride\'s progress; [LB] TARGETS / WHEEL faded top right without a target; GOALS and TAKE CONTROL in the left lane.'},
        { img: CAP('f_jump'), title: 'Jump tunnel', cap: 'In a cinematic (the game\'s letterbox) HUD 2 collapses to the maneuver chip: JUMP COLORADO with the countdown.' },
        { img: CAP('f_turret'), title: 'Turret view', cap: 'TURRET VIEW chip in the nav; X held toggles turret view (on and off), EXIT TURRET on the context line; the reticle stays centred, the right stick turns the camera.' },
        { img: CAP('f_missile'), title: 'Alert: missile incoming', cap: 'One alert at a time, top centre under the comm panel: MISSILE INCOMING with its answer (the D-pad direction of the flares), the countermeasure slot lit on the cross.'},
        { img: CAP('f_m03'), title: 'Protect objective (M03)', cap: 'The objective as the headline with the convoy\'s hull bar; the escorts by their call signs; a wrapped weapon row.' },
        { img: CAP('f_720p'), title: '1280x720', cap: 'Every size is a fraction of the screen height: the same layout at 720p, 21:9 and 4:3.' },
        { img: CAP('t_43_fight'), title: '4:3 (1600x1200): HUD 2 at 0.8', cap: 'At 4:3 HUD 2 takes 0.8 of its 16:9 size (16:10 0.9), so the panels keep their spacing across the narrower screen; text stays at the legibility floor or above. A Rheinland fight in Bretonia (M05): the objective as the game shows it, two identical guns as "Magma Hammer Mk I ×2".'},
        { img: CAP('t_43_alert'), title: '4:3 at the largest text: the alert keeps clear', cap: 'Text size 150 % and HUD size 130 % (HUD 2 caps its scale at what the screen holds, about 118 %): the alert sits below the ring and the chat band ends above it.' },
        { img: CAP('t_vanilla_fight'), title: 'Vanilla Freelancer 1.1 (1280x960)', cap: 'The same HUD on the original game at 4:3 (0.8): Agency FB from Windows\' fonts, the own-ship view drawn without HDE\'s plugins, the objective without vanilla\'s stray format code ("Destroy the Hostile Ships", not "...Ships%M").' },
      ] },
      { t: 'p', html: `<b>Text at every size:</b> every text FLvibed draws follows one rule: a text that does not fit its box first steps down in size, only as far as needed, to a legibility floor (0.024 of the screen height, never under 14 px, whatever <i>Text size</i> and <i>HUD size</i> say); only then does it show its start with "..." - on HUD 2 it then waits 1.5 s, scrolls slowly to its end, waits again and fades back to its start, like a station's display board - or, where the box takes lines, it wraps (the objective onto two lines). Nothing inside a panel or card touches anything else in it (at least 0.01 H apart). HUD 2 grows with <i>Text size</i> x <i>HUD size</i> (never below 100 %) times the screen's shape - 16:9 and wider 1.0, 16:10 0.9, 4:3 and 5:4 0.8, so narrower screens keep the spacing - but never past what its panels fit on the screen (about 118 %); texts never go under the floor. Identical guns show once with their count ("Justice Mk I ×2"). <b>Tooltips</b> (the game's hover help, both HUDs) show only on a deliberate hover: in flight after a real mouse move within the last 3 s, never for a cursor resting on a HUD button while the stick or the autopilot flies; in bases, menus and the NeuroNet windows the game's own hover - the mouse, the pad cursor or a pad focus.` },
      { t: 'table', title: 'Where things are', head: ['Zone', 'What it shows'], rows: [
        ['Top left: <b>nav</b>', 'NEURONET (View / its key) on the top line; the objective as the headline, exactly as the game shows it (values filled in, format codes dropped; also right after loading a save; yellow diamond; wraps onto two lines) with a protected ship\'s hull bar; system and zone (dim); the maneuver chip while one runs (AUTOPILOT when FLvibed flies) with progress, ETA, dock / lane / jump answers.'],
        ['Top centre: <b>comms and alerts</b>', 'The subtitles\' panel with the speaker\'s portrait; one 3 s alert card (shield failing, missile, hull critical, cruise disrupted, cargo full) naming the button that answers it. The alert and the subtitles always keep clear of each other: it goes under the panel, or below the ring where the screen is narrow (4:3), and the chat band and the Neural Net column make room for it.'],
        ['Top right: <b>target card</b>', 'The game\'s 3D view of the target (ships, stations, planets, gates; else its flat icon), attitude, class, level, name, faction (live reputation), distance, shield and hull. [RS] x2 CLEAR in its footer row. In a fight the threat list under it (LB TARGETS, RS NEXT, the next hostiles). Without a target the corner shows [LB] TARGETS and [LB held] WHEEL (faded outside combat). The subtitles\' Neural Net column sits under it.'],
        ['Centre: <b>reticle ring</b>', 'Shield left, hull right, power below, the speed inside; the throttle arc at its bottom centre with BOOST / KILL / REV beside it; the cruise state inside the ring under the speed (the charge seconds while the bottom arc fills, then CRUISE ON; the power arc steps aside meanwhile); missile chevrons and an amber hit flash on the side you were hit. ' + UP('new in 0.2.0')],
        ['Left middle: <b>chat band</b>', 'Ambient radio chatter, newest lowest, three lines; the cards stay through in-flight cutscenes (docking, launching, mission scenes).'],
        ['Bottom left: <b>ship</b>', 'A 0.31 x 0.15 H panel: your ship\'s wireframe; calm: name and class, hold and credits; fight / formation: up to three escorts with hull bars. It grows for a long credit count (up to 0.36 H), so CREDITS stays whole; only past that does the word shorten to CR.'],
        ['Bottom, beside the panels: <b>prompt lanes</b>', 'At most three actions you can take now, in two lanes: moving and controlling the ship on the left beside the ship panel (DOCK, GO TO, CRUISE / CANCEL CRUISE, DROP CRUISE, STOP, ABORT DOCK, TAKE CONTROL, MAP ...), firing, using and targeting on the right beside the loadout (TURRET / EXIT TURRET, TRACTOR &lt;item&gt;, TRACTOR ALL n, NEAREST ENEMY or TARGET AHEAD, TARGETS); two rows each. ' + UP('new in 0.2.0')],
        ['Bottom centre', 'Empty: from just below the ring to the screen\'s bottom across the middle fifth of the screen HUD 2 draws nothing, so your ship stays in view (the game\'s own brackets and reticle still show there). ' + UP('new in 0.2.0')],
        ['Bottom right: <b>loadout</b>', 'The weapons panel (0.40 x 0.15 H): the gun groups (Y held cycles; the active one marked; identical guns once with their count, "Justice Mk I ×2"), the launcher with ammo and LOCKED, a torpedo (or a cruise disruptor on a ship with no torpedo) on a row of its own that says HOLD on the pad; above its right end the D-pad cross on its own plate (nanobots up, batteries down, countermeasures left, mines right, each count beside its icon).'],
      ] },
      { t: 'settings', title: 'HUD 2 settings (CONTROLLER > HUD)', keys: ['hud_style', 'hud_preset', 'hud_fade', 'hud_opacity', 'hud_scale', 'hud_numbers', 'hud_threats', 'hud_context', 'hud_alerts', 'hud_info', 'hud_wireframes', 'hud_transition', 'text_size'] },
      { t: 'dev', html: `<p><b>Principles (UI_HUD2 1, as built):</b> the game's HUD hidden per root through its own state byte (looked up by name, revalidated; a missing root stays native); status around the reticle (ring radius 0.10 H, arcs at least 0.0065 H thick, numbers only below 40 % by <code>hud_numbers</code>); plates only where text must hold over scenery (target card, ship, loadout, alert, pills); boxed area about 10 % (native about 22 %); text at least 0.024 H, glyphs 0.032-0.036 H, keycaps grow around their name; one meaning per symbol (diamonds = objectives, chevrons = missiles, amber 0.008 H hit arc over 300 ms, only when hull or shield fell within 0.5 s).</p>
<p><b>States:</b> calm dims (ring 40 %, speed / throttle 60 %, panels 60 / 65 %); combat full with threats and escorts; cruise charge = the bottom arc 48-132 degrees; throttle arc 82-98 degrees at R + 0.022 (bottom centre, 26 Oct 2026; the ring's lowest drawn edge) with its word right of it from cx + 0.068 H; the cruise state inside the ring at + 0.083 H (the speed at + 0.045 while it charges or runs); letterbox (<code>exe::LetterboxAmount</code> &gt; 0) collapses to the nav chip and ring; under a modal menu (<code>ui_style</code> 1) the whole flight HUD steps away (<code>hudvis::SetMenuOver</code>). Alerts arm 1.5 s after entering space and only on a live hull; the slot an alert names lights (amber <code>#E8A33A</code> when used up / not fitted).</p>
<p><b>One value, one place:</b> the nav's dock / lane / jump answer leaves while the comm panel shows a line (HUD bus); the subtitles leave out Neural Net lines HUD 2 shows as alerts; the chat feed waits while the top panel speaks; the game's chat window hidden under HUD 2 (kept while typing), in in-flight cutscenes too, where the feed keeps its cards (<code>hudvis::HoldChat</code>, the bus's <code>HudLayout.feed</code>). The alert keeps clear of the subtitles through the bus, one owner each way: HUD 2 moves the alert off the published dialogue rectangle (below it, above it, below the ring), the feed and the Neural Net column read the alert's rectangle and yield (the feed narrows beside it or ends above it). Hidden native parts: damage arcs, the red missile icon, the native arrival line; the game's ToolTip / Rollover in flight unless a real mouse move came within 3 s (<code>hudvis::SetHoverHelp</code>, hidden the game's own way so its hover timer restarts; both HUD styles).</p>
<p><b>Text:</b> <code>core\\game\\textfit.h</code> (host-free tests) - step down, solved, to <code>textfit::MinSize</code> = max(0.024 H, 14 px), then ellipsis or <code>hud2kit::FitLines</code>; results cached per string / size / box / font set (<code>hud2 state</code> kit fits / fitMisses). HUD 2's k = max(<code>hud_scale</code> x <code>text_size</code>, 1) x aspect (the usable width 0.9 W against 16:9's 1.6 H, clamped 0.8..1: 16:9+ 1.0, 16:10 0.9, 4:3 / 5:4 0.8; never lower - panel rows are spaced for floor text), then capped at what the bottom row, the right column and the centre column with the alert hold (max 0.426 / 0.36 = ~1.18); <code>hud2 state</code> prints the <code>layout</code> line (k, aspect, the zones, overlaps). <b>Objective:</b> the host formats entry 0 of every SetMissionObjectives through the game's own formatter (<code>exe::FmtStrFormat</code>, HostApi v24 ObjectiveText); after a save load (Content.dll reloads and the objective comes back before its hooks do) it re-reads the game's own copy once (<code>exe::ClientObjective</code>, v25 ObjectiveReread) - no polling. The kit keeps two font sets swapped in O(1) and never builds its atlas under the floor.</p>
<p><b>Kept native (decided):</b> the target brackets with their own label and bars, the lead indicator and off-screen arrows (a hook in the indicators' draw is not robust enough); the subtitles' <code>hud_arrows</code> keeps them clear of HUD 2's rectangles. The own-ship view is the status panel's own 3D view, drawn by FLvibed through the panel base's routines on every build (no HDE plugin needed; see Install).</p>
<p><b>The 31 Oct 2026 layout</b> (<code>docs\\UI_HUD2.md</code> 5.19-5.23, <code>UI_HUD2_PRESETS.md</code> 7): both bottom panels 0.15 H tall - ship 0.31 (icon column 0.085, texts from 0.107, values 0.014 before the edge), loadout base 0.40 (K&amp;M 0.44) with the cross 0.20 x 0.15 stacked 0.012 above its right end; tight keycaps (1.2 x the 0.024 name) in the loadout, the maneuver row and the prompt lanes; each slot's count at the floor beside its icon. Prompt lanes (<code>promptfit.h</code> <code>PlaceLanes</code>, <code>hud2.cpp</code> <code>CtxSide</code>): left from the ship panel + 0.024 to 0.40 W, right from 0.60 W to the loadout - 0.024, rows at 0.915 / 0.855 H; a prompt too wide is squeezed and its label scrolls; with no room beside the panels (4:3 / 5:4 at large scales) the same lanes above the panels. Marquee (<code>core\\game\\marquee.h</code>): cut start form, hold 1.5 s, scroll 0.05 H/s, hold 1.5 s, 0.25 s fade reset; no reduced-motion switch yet. Lint (<code>hud2_lint.h</code>): FAIL <code>panel.overlap</code> (items of one panel closer than 0.01 H) and FAIL <code>zone bottom</code> (anything HUD 2 draws in x 0.40-0.60 W from the ring's lowest edge + 0.01 H, ~0.634 H, down; the hit flash and missile chevrons excepted). The Focus preset (experimental; <code>hud_preset</code> 1, a hidden advanced row; Speedrun and Guided are planned) has its band of state words at the centre + 0.078 H inside the arcs' circle (<code>UI_SPEC.json</code> <code>hud2_presets</code>) and hides a full meter in calm (a not-full one at reduced opacity). These frames are drawn (<code>tools\\uimock\\hud2_states.py</code>); the in-game lint passes 0 FAIL for Standard and Focus, but no release-build capture of this layout is on the page yet.</p>
<p><b>K&amp;M form</b> (<code>hud_style</code> 2 with keyboard and mouse): keycaps from the live keymap, the maneuver chips, list rows and gun groups click (the game's own commands); the loadout base 0.44 H wide (pad 0.40 H) with the consumables as a 2 x 2 key grid on the cross's plate; the nav rectangle 0.338 H (pad 0.29 H). Readers: <code>core\\game\\hudinfo.h</code>. Perf: hud2.Update 27 us + Render 35 us + OnRenderUnderHud 22 us (release, 4K fight, after FIX-TEXT). Code <code>controller\\src\\impl\\hud2*.cpp</code>, <code>hudvis.*</code>, <code>core\\hud_bus.*</code>.</p>` },
    ] },

  { id: 'classic', nav: 'Classic HUD', title: 'Classic HUD with the pad layer',
    lead: `Prefer the game's own flight HUD? Set HUD to CLASSIC. Every panel stays exactly where Freelancer puts it, and with a controller FLvibed only adds what a pad player needs: the button's glyph on each HUD control it works, a short list of the actions available now, and a status line while the autopilot flies. With keyboard and mouse the classic HUD is the game's, plus one extra button on the maneuver bar for the autopilot.`,
    dv: { pad: 'With the controller: glyph badges on the HUD and the button legend.', km: 'With keyboard and mouse: no badges and no legend, the game\'s HUD as it is, plus the maneuver bar\'s autopilot button (key K).' },
    blocks: [
      { t: 'gal', items: [
        { img: CAP('f_travel_cl'), title: 'Badges and legend, calm', cap: 'Glyphs on the maneuver bar\'s bottom edge (B free flight, A dock, A held formation, View held autopilot), Y on the cruise box, the D-pad glyphs over the consumables; right middle the legend: DOCK AT FORT BUSH, CRUISE, TARGETS, TARGET AHEAD, MAP.',
          km: { img: CAP('f_classic_km'), title: 'The game\'s HUD with keyboard and mouse', cap: 'Nothing added but the autopilot button on the maneuver bar and FLvibed\'s other features (subtitles, hit effects); the legend and badges belong to the controller.' } },
        { img: CAP('f_combat_cl'), title: 'Badges and legend, combat', cap: 'The legend in a fight: FIRE GROUP 1, AFTERBURNER, MISSILE, NEXT ENEMY, NANOBOT 3, BATTERY 3, COUNTERMEASURE, MINE, REVERSE (held).', only: 'pad' },
      ] },
      { t: 'settings', title: 'Classic HUD settings', keys: ['hud_glyphs', 'button_legend', 'ap_status_line', 'world_prompts', 'ap_hints', 'maneuver_button', 'autopilot_key'] },
      { t: 'dev', html: `<p><b>Badges</b> (<code>padhud.*</code>, reworked 25 Oct 2026): anchored to the HUD's controls by NAME, never by pixel; 0.45 of the element's height (0.022-0.036 H, times <code>text_size</code>), centred on the panel's frame line that faces the open screen; the HUD's own chrome and font, the game's yellow when the element is lit; the pressed D-pad arm highlighted. <b>Legend</b> (Lost Judgment pattern): right middle, only what applies now, at most 9 rows, HOLD = a thin bar under the glyph plus the word; a non-dockable target reads GO TO &lt;name&gt;, loot TRACTOR &lt;name&gt;; the AUTOPILOT row after the autopilot was used once or with <code>ap_hints</code>; it steps aside while a modal has its own prompt bar and shifts up to clear the bottom panels.</p>
<p><b>Maneuver bar button</b> (K&amp;M): the fifth button with FLvibed's mesh (<code>controller\\data\\autopilot.3db</code>), lit while the autopilot flies, key <code>autopilot_key</code> (a key the game binds is refused); the bar's frame grows right by one button, the game's four buttons stay. <b>Status line</b> under the bar while the autopilot flies, cruise charges or turret view is on. <b>Flight modals</b> over either HUD: the target picker (LB tap), the action wheel (LB hold), the goal panel (X while the autopilot flies; QUEUE / DO NEXT greyed: no goal queue yet).</p>` },
    ] },

  { id: 'cues', nav: 'Hit effects', title: 'Hit effects: shield, hull and reticle cues',
    lead: `When you are hit you should feel it without reading a number. FLvibed draws short effects at the screen edges, <b>under</b> the HUD so every panel stays crisp: a shield hit flares in your own shield's look (each faction's shields have their own hit effect in the game's data) tinted by the weapon that hit you, on the side it came from; a shield failure bursts from all edges; with the shield down every hull hit leaves a hexagon pattern that only hull damage carries, and as the hull falls the edges glow and burn, breathing slowly when the hull is critical. Around the reticle, a ring pulses when the autopilot takes over (cyan, outward) or hands back (amber, inward) and when you use a nanobot (green) or a shield battery (blue). <b>They are on by default</b> and can be turned off in Options &gt; FLVIBED &gt; CONTROLLER &gt; HUD (Shield hit cue, Hull hit cue, Reticle cue).`,
    dv: { pad: 'Captured with the controller; the effects are the same on every device and HUD.', km: 'The same with keyboard and mouse: the effects do not depend on the device (shown: the real fight on the classic HUD with keyboard and mouse).' },
    blocks: [
      { t: 'table', title: 'Verified in game (25 Oct 2026, release build, SaveC705, two pirates firing; the cues switched on)', head: ['Cue', 'Classic HUD (hud_style 0)', 'HUD 2 (hud_style 1 / 2)', 'Under a menu'], rows: [
        ['<b>Shield hits</b> (the edge flare at the hit side)', OK('real fire: pad and K&amp;M'), OK('real fire: pad and K&amp;M'), OK('hidden (pause menu, both ui_style values)')],
        ['<b>Shield failure</b> (rings and a white edge burst)', OK('real break + test'), OK('real break + test'), OK('hidden')],
        ['<b>Hull</b> (hits with the shield down, the damage glow, hexagons)', OK('real hull hits + test'), OK('real hull hits + test'), OK('hidden')],
        ['<b>Reticle rings</b> (autopilot on / off, nanobot, battery)', OK(), OK(), OK('hidden')],
      ] },
      { t: 'cmp', title: 'Shield failure', cl: CAP('c_break_cl'), h2: CAP('c_break_h2'), ll: 'CLASSIC HUD', rl: 'HUD 2', cap: 'The shield fails: rings around the edges and a white-and-shield-colour burst, brightest toward the hit (here from above). Under the HUD: the panels stay readable on top.' },
      { t: 'cmp', title: 'Hull damage with the shield down', cl: CAP('c_hull_cl'), h2: CAP('c_hull_h2'), ll: 'CLASSIC HUD', rl: 'HUD 2', cap: 'Low hull: the red hexagon lattice along every edge (only hull damage carries it; hexagons by default, armour plates as an option), the glow strongest at the bottom; it breathes below the game\'s own HULL BREACH IMMINENT point (20 %).' },
      { t: 'gal', title: 'In a real fight and around the reticle', items: [
        { img: CAP('c_real_pad'), title: 'Real fire, classic HUD (controller)', cap: 'Shield hits from the right while two pirates attack; the edge flare sits on the side the rounds came from.', km: { img: CAP('c_real_km'), title: 'Real fire, classic HUD (keyboard and mouse)', cap: 'The same fight a moment later with keyboard and mouse: the flares on the right edge.' } },
        { img: CAP('c_real_h2'), title: 'Real fire, HUD 2', cap: 'Just after the shield failed under fire: the failure rings at the right edge, HUD 2\'s ring showing the shield gone.' },
        { img: CAP('c_ring_ap'), title: 'Reticle ring: autopilot engaged', cap: 'A cyan ring expanding outward around the crosshair (amber, contracting, when it hands back).' },
        { img: CAP('c_ring_nano'), title: 'Reticle ring: nanobots used', cap: 'A green double ring (shield batteries: blue).' },
        { img: CAP('c_modal'), title: 'Under a menu', cap: 'The pause menu over the flight with the hull critical: no cue is drawn while it is open, back the frame it closes.' },
      ] },
      { t: 'p', html: `<b>Vibration</b> ${UP()}: the screen cues have a touch counterpart on the controller (<code>rumble</code> in CONTROLLER &gt; STICKS, 0 = off). A hit's strength follows its share of your shield and hull (the hull feels heavier than the shield), a shield failure and the autopilot's hand-back have their own pulses, and a game box waiting for your answer ticks twice. It never is the only cue, stays silent while the game is in the background, in menus and cutscenes (while paused only for those boxes) and while you play with keyboard and mouse. Design and numbers: <code>controller\\docs\\HUD_CUES.md</code> "Haptics". Not built yet: per-category strength, trigger rumble, DualSense effects, explosions and engine rumble (Not implemented yet).`, only: 'pad' },
      { t: 'settings', title: 'Cue settings (CONTROLLER > HUD)', keys: ['shield_cue', 'shield_cue_intensity', 'hull_cue', 'reticle_cue', 'rumble'] },
      { t: 'dev', html: `<p><b>Design:</b> <code>controller\\docs\\HUD_CUES.md</code> (one cue = one meaning, under 3 Hz, never colour alone, an off switch). <b>Shield:</b> the fitted shield's hit effect read from the game data at run time (<code>core\\game\\hitlook.*</code>: shield arch -&gt; its .ale layers, textures, colour / alpha / size keys; the same join as <code>tools\\hitfx.js</code>, table <code>docs\\kb\\hit_effects.md</code>), tinted 35 % toward the hitting round's impact colour (<code>space::TrackRounds</code>), strength by the damage burst over 0.5 s, at most ~3 groups per second, 12 segments per edge weighted toward the hit; direction from the point the game feeds its own damage indicator (<code>exe::DmgIndSource</code> / <code>DmgIndContact</code>, HostApi v12), then the tracked round, then the nearest attacker. <b>Hull:</b> the ship's own hull-hit look (<code>hitlook::Hull</code>), the damage stages at the game's fuse thresholds (<code>hitlook::DamageStages</code>), the pattern <code>hull_cue_pattern</code> (2 hexagons default, 1 plates, 0 none; ini only), critical at <code>exe::HullCriticalFrac</code>. <b>Reticle:</b> <code>reticlecue.cpp</code>, 0.55 s rings at ~0.11 H, from the edges of <code>autopilot::Active()</code> and drops of the nanobot / battery counts.</p>
<p><b>Layering:</b> drawn in <code>OnRenderUnderHud</code> (the host's detour on the UI pass <code>exe::UiRender</code>: after the 3D scene, before any HUD control); the overlay is the fallback when that hook is refused; the reticle rings in the overlay. <b>Gating:</b> space only; not drawn while a HUD 2 menu modal is open (<code>uiskin::ModalOpen</code>, controller.cpp <code>g_menuOver</code>); with <code>ui_style</code> 0 (or the Classic HUD) the game's pause menu pauses the space frame, so none shows either (seen in game). Debug <code>cue status | hit | break | hull [dmg] [munition] | hullpts &lt;hp&gt;|off | dir &lt;deg&gt;|off | ring 0..3</code>. The 25 Oct 2026 run: <code>research\\experience\\runs\\spec_flvibed_2026-10-25\\</code> (cues.log, cues2.log, cues3.log: real hits 9, breaks 1, hull hits 11 counted across hud_style 0 / 1 / 2 and both devices). Note: a single simulated shield hit at full shield is faint by design (alpha 0.45, rest 0.4); the failure and hull cues are the strong ones.</p>` },
    ] },

  { id: 'screens', nav: 'Menus and bases', title: 'Menus, bases and dialogs: HUD 2 in the menus and bases',
    lead: `With HUD 2 on (the default) the game's menus, rooms, dealers and dialogs take HUD 2's look: the purple art is hidden and dark glass drawn underneath, while every window, row, button, text and position stays the game's own, so nothing behaves differently. It adds a context strip (base, room, system, credits, cargo, ship), a name card over the character you point at, and decision numbers where the game already knows the answer (price words, compare lines, trade-in). It is part of HUD 2 and on by default; the advanced row <b>Menus and rooms look</b> set to Classic gives the game's own look back, any time, even with a window open (Classic HUD shows the game's look everywhere). The controller's button prompts sit in one lane at the bottom right in both looks.`,
    dv: { pad: 'Captured with the controller: the prompt pills and the focus mark are the controller\'s.', km: 'With keyboard and mouse these screens look the same minus the prompt pills and the focus mark (the name card follows the mouse hover). The captures below were made with the controller; no separate keyboard captures exist.' },
    blocks: [
      { t: 'family', title: 'Base rooms', text: 'Every docked screen shares one frame: the room bar on one slim glass bar with the current room underlined, the NeuroNet box on glass, the context strip top left. On the pad LB / RB step through every room, on stations too.', items: [
        ['room_trader', 'Commodity trader room', 'The strip names the base, the room (from its own button) and the system, with credits, cargo and ship; the HUD 2 name card (faction over the name, an accent in the attitude colour) replaces the grey tooltip.'],
        ['room_bar', 'Bar', 'The card keeps off the other characters\' heads. Prompts: D-pad CHARACTER · Y JOB BOARD · X NEWS · LB RB ROOM, and A TALK on anyone but yourself (Trent).'],
        ['room_launchpad', 'Launch pad', 'Your own character is the default focus; no A pill on him (his click starts nothing). The strip wraps or drops its least important values on narrow screens.'],
      ] },
      { t: 'family', title: 'Base windows', text: 'The game\'s windows keep every control; their art is hidden and glass drawn underneath, so the game\'s buttons still click by name.', items: [
        ['jobboard', 'Job board', 'One plate with a header rule; the one focus style on the selected job; the job type beside the reward.'],
        ['news', 'News', 'The plate trimmed above the prompt lane; A SELECT, B CLOSE.'],
        ['offer', 'Mission offer', 'The giver top right of the body; A ACCEPT · B DECLINE. A subtitle line sits beside the lane under the window, never over its buttons.'],
      ] },
      { t: 'family', title: 'Dealers', text: 'Four plates per dealer; credits and cargo move to the strip, where a purchase the game allows shows yellow deltas. An item you cannot buy (no free hardpoint, say) keeps the full centre panel and the infocard\'s backing, so its text stays readable and the prompts stay off it.', items: [
        ['commodity', 'Commodity dealer', 'GOOD / FAIR / HIGH beside the game\'s coloured square (the game\'s own verdict); the strip\'s deltas match the Total line; LB RB SIDE switches your cargo / the dealer. The pills stand in a column right of the description.'],
        ['equipment', 'Equipment dealer', 'A compare column in the transfer panel: the selected gun against the one mounted (damage, refire, range), across the panel\'s whole width; a long heading takes a second line.'],
        ['shipdealer', 'Ship dealer', 'The game\'s refusal first ("NEEDS LEVEL 1", amber), then TRADE-IN and NET; no strip delta for a purchase the game refuses.'],
        ['repair', 'Repair', 'Joins the family; a pad screen of its own.'],
      ] },
      { t: 'family', title: 'NeuroNet windows', text: 'Inventory, player status, log and help on the same glass; the inventory\'s own credits and cargo give way to the strip.', items: [
        ['nn_inventory_docked', 'Inventory', ''], ['nn_playerinfo_docked', 'Player status', ''], ['nn_log_docked', 'Neural net log', ''], ['nn_help_docked', 'Help', ''],
      ] },
      { t: 'family', title: 'Menus and dialogs', text: 'Modal menus get a 70 % navy scrim, one plate per panel and HUD 2 tab plates; in space the whole flight HUD steps away while the menu is open.', items: [
        ['pause_docked', 'Pause (docked)', ''], ['pause_space', 'Pause (in space)', 'The flight HUD hidden under the menu, back on resume.'],
        ['save_dialog', 'Save', 'The side buttons on HUD 2 plates.'], ['osk_save', 'Save with the on-screen keyboard', 'FLvibed\'s keyboard for the pad; its prompts beside it.'],
        ['load_ingame', 'Load (in game)', ''], ['confirm_docked', 'Quit confirmation', 'Focus starts on NO: A NO · D-pad CHOOSE · B NO.'],
        ['options_ingame_video', 'Options (in game)', 'The page tabs on HUD 2 tab plates; A SELECT · B BACK.'], ['options_front_video', 'Options (main menu)', 'At 16:9 the pills take a column right of the plate; at 4:3 a bottom row or column since the fit-rule lane (FIX-TEXT, measured at 1600x1200 and vanilla 1280x960).'],
      ] },
      { t: 'gal', title: 'Dialogs and popups (0.2.5)', items: [
        { img: CAP('x_popup_h2'), title: 'Mission / tutorial popup', cap: 'The first mission\'s tutorial popup on a HUD 2 plate; same text and buttons as the game\'s.' },
      ] },
      { t: 'family', title: 'Left as the game draws them', text: 'Decided against a restyle; they still get the pad\'s prompts and focus.', items: [
        ['mainmenu', 'Main menu', 'Since 0.2.5 it takes HUD 2\'s look too (same layout and controls).'], ['load_front', 'Load (main menu)', ''],
        ['newgame_prompt', 'New Game prompt', 'FLvibed\'s own prompt (see Speedrun and New Game).'], ['navmap_docked', 'Nav map (docked)', 'The map\'s frame draws outside the path the skin can trust.'],
        ['navmap_space', 'Nav map (in space)', ''], ['death', 'Mission failed', 'Focus on LOAD AUTOSAVE.'],
        ['chat_space', 'Chat with the on-screen keyboard', 'The pills in a column right of the Console field.'],
      ] },
      { t: 'gal', title: 'Other aspect ratios (HUD 2 only)', items: [
        { img: CAP('t_43_room'), title: '4:3 room (1600x1200)', cap: 'The prompt lane stays at the bottom at 4:3: before any other lane the pills try the row with their labels at the legibility floor, a column, two rows at the bottom.' },
        { img: CAP('t_43_jobboard'), title: '4:3 job board', cap: 'Four pills in the bottom row.' },
        { img: CAP('t_43_pause'), title: '4:3 pause (docked)', cap: 'A SELECT · B RESUME in the bottom row.' },
        { img: CAP('t_43_equipment'), title: '4:3 equipment dealer: the one exception', cap: 'Its infocard plate covers the bottom band to 0.975 H and 0.91 W, so the pills take the top lane under the NeuroNet box in two rows (geometry, not text). Every other screen keeps the bottom lane.' },
        { img: CAP('a_1610_commodity'), title: '16:10 commodity dealer', cap: 'The top lane, two rows (captured before the fit-rule lane, which now tries the bottom rows with the labels at the floor first; 16:10 not re-measured).' },
        { img: CAP('a_1610_shipdealer'), title: '16:10 ship dealer', cap: 'The column right of the window.' },
        { img: CAP('a_21x9_room_trader'), title: '21:9 trader room', cap: 'Everything in its row at the bottom right.' },
        { img: CAP('a_21x9_commodity'), title: '21:9 commodity dealer', cap: 'The column.' },
        { img: CAP('a_21x9_jobboard'), title: '21:9 job board', cap: '' },
        { img: CAP('a_21x9_pause_docked'), title: '21:9 pause', cap: '' },
      ] },
      { t: 'p', html: `<b>Closing a dealer with B</b> (both looks): the game drops a close while the dealer window is still sliding in (about half a second, the original game too), so the pad holds your B and closes the window the moment the slide ends - one press always closes; no empty plates flash at the close. With the focus on the transfer panel (its BUY / SELL button or the quantity slider) B goes back to the selected row instead (B BACK in the prompt bar) ${UP()}; B on a row closes. <b>The game's own popups</b> (the tutorial boxes and mission message boxes, e.g. in M01): A presses the box's own OK / YES, B its CLOSE / NO / LATER (A OK · B CLOSE in the prompt bar), also when B is the first pad press; the B or A that closes one never reaches the ship. Not yet verified on a real pad.`, km: { html: `<b>Closing a dealer</b>: the game drops a close while the dealer window is still sliding in (about half a second, the original game too); click again after the slide. <b>The game's own popups</b> (tutorial and mission boxes) are the game's, clicked as always.` } },
      { t: 'p', html: `<b>What stays the game's:</b> the loading screen, the nav map's drawing and frame, the welcome texts, the repair window's art, the scroll bars, every text size, the confirm dialog's own dimming box.` },
      { t: 'settings', title: 'Settings', keys: ['ui_style', 'prompt_bar', 'pad_cursor', 'cursor_magnet', 'cursor_speed', 'text_size'] },
      { t: 'dev', html: `<p><b>The skin, not the screens:</b> plates, rules, focus and anchors from the window's native control rects at open (fractions of H only for padding); art hidden by state bit 1 (re-cleared per frame where the game toggles it) or the base draw's mesh handle +0x84 = -1 after the draw-slot check; titles recoloured via +0x348 only; glass, scrim and focus fill in <code>OnRenderUnderHud</code>, strip / pills / card / words in <code>OnRenderOverlay</code>; windows found on the host's UI generation counter (HostApi v23); an unknown window stays native. <code>ui_style</code> 0 changes nothing (the row applies only while <code>hud_style</code> is not Classic); switching restores every byte at once (the dealer panels' pose re-applied: <code>uiskin</code> Repose).</p>
<p><b>Glass</b> 85 % with a CHROME 70 % rim of 0.0013 H; header rules from the title control's extent; empty plates collapse. <b>Focus</b>: one style - active yellow at 28 % on the drawn element with yellow edges and a 0.005 H bar outside its left edge; the source is the selected row (flag +0x35C bit 0x10), one mark per screen, never on a disabled or current-page button. <b>Strip</b>: base 0.036 H, room (active small caps), system (chrome); CREDITS / CARGO / SHIP labels 0.024 H, values 0.030 H; yellow deltas only when the game allows the deal; width budget = the room bar's left edge - 0.05 W - 0.03 H (wraps, then drops ship, then system). <b>Card</b> (<code>uistrip</code> PlaceBy): inside the safe area, never over its character, of the allowed places the one covering the others least (heads weigh 20x), then the least moved. <b>Decision numbers</b> only from data the game holds (IDS 1047-1052 deal verdicts, the game's Total line, trade-in = hull + equipment), else nothing.</p>
<p><b>The bottom lane</b> (<code>promptbar.cpp</code>, both looks; UI_HUD2_EXTENDED 13): (1) one row right-aligned at 0.05 W in the band 0.910-0.950 H; HUD 2 pills 0.040 H (glyph 0.032 H, verb 0.026 H); (2) keep-outs in 2D: every open window's plates, tabs, the room bar and NeuroNet box, the strip / card / words, the QUANTITY line, the OSK panel, the chat's Console field, HUD 2's panels under a menu in flight; (3) trim plates that end in the band to content + 0.006 H; (4) on a collision, through the fit rule first: the row with the labels at the legibility floor, the column at the labels' size, two rows at the bottom at the floor (<code>lane=rows</code>), the column at the floor; then a column right of the window (bottom 0.950 H, 0.008 H apart) if as wide as the widest pill, else docked the top lane under the NeuroNet box in as many rows as fit, elsewhere the nearest legal band - nothing below 0.95 H; (5) subtitles: the lane and the windows' floor are published on the HUD bus (v3: <code>HudLane</code>, <code>HudFloor</code>, <code>HudDockedSubs</code>); the block stays 0.010 H above the lane and under the window, and where it cannot fit the lane yields; (6) A and B on every menu (main menu and death dialog: A only).</p>
<p><b>Open:</b> see "Not implemented yet". Perf: 35-40 us per frame (skin), 67-84 us all of HUD 2 in the menus at 4K; the pad navigation's probe cache (all pad players): 7.4 ms -&gt; 65-80 us per frame on a dealer.</p>` },
    ] },

  { id: 'controls', nav: 'Controls', title: 'Controls: controller and keyboard',
    lead: `Three flight layouts for the controller, one set of menu controls for every screen, and the game's own keys for keyboard and mouse. Holds can become toggles, the confirm button can swap for Nintendo pads ${UP()}, and the glyphs follow your pad (Xbox, PlayStation, Switch) or your choice. The tables follow the Input buttons above and the layout chosen on the options page.`,
    dv: { pad: 'The controller layouts first, with this pad\'s glyphs; the keyboard table folded below.', km: 'The keyboard table first (keycaps); the controller layouts folded below.' },
    blocks: [
      { t: 'binds' },
      { t: 'p', html: `<b>Weapon groups</b> (<code>weapon_groups</code>): SIMPLE = RT fires the active group, switch in the action wheel; CYCLE ON Y HOLD (default) = Y held flips to the next group, Y tap stays cruise; TWO GROUPS ON THE TRIGGERS = RT group 1, LT group 2 (afterburner moves to the LS click). Launchers fire only on their own buttons. <b>Turret view</b>: X held (FREELANCER); ASSISTED is built on it - the autopilot flies, you aim and fire (its gameplay flow is not settled yet: see "Not implemented yet"). <b>The autopilot</b> is one hold away in every layout (View held half a second); any stick past <code>autopilot_cancel</code> hands the ship back.`, only: 'pad' },
      { t: 'p', html: `<b>Hold buttons are marked on the glyph itself.</b> A prompt for an action you must <i>hold</i> (not tap) carries an extra outline: on HUD 2 and in HUD 2's prompt pills a <b>broken outer ring</b> (four arc segments) around the glyph; on the classic HUD's badges and button legend a thin bar under the glyph. The mark is the hold's signal and must stay visible at every size. The word <b>HOLD</b> is written too, small and dimmer than the label: on HUD 2's context line and prompt pills <b>before the glyph</b> (HOLD, the ringed glyph, then the action); in the classic legend and the classic prompt bar after the label. Only the classic HUD's badges on its own controls show the bar alone (no room there: the legend carries the word). Where HOLD before the glyph would push a prompt off HUD 2's line or lane, it moves instead - in this order, the first that keeps every prompt: stacked above the glyph; inside the ring's gap (only if legible at the smallest text size - in practice never); above the action's name; one HOLD before a run of hold prompts; and only as the last resort the ring alone. Today that means combat at 16:9 shows HOLD above both REVERSE and TURRET, and the 4:3 turret / autopilot prompts carry it above their glyph or name. A hold that is running sweeps along its prompt.`, only: 'pad' },
      { t: 'p', html: `<b>Pad cursor</b> (default EVERYWHERE): the left stick shows a cursor on menus, rooms, dealers and the map that slows over and pulls toward targets; a D-pad or bumper press hides it and focus carries on; A clicks either way. <b>Text</b>: FLvibed's on-screen keyboard (A type, X space, B backspace, Menu done).`, only: 'pad' },
      { t: 'cmp', title: 'Glyph look on HUD 2', cl: CAP('g_h2_look0'), h2: CAP('g_h2_look1'), ll: 'AUTOMATIC', rl: 'COLOURED', cap: 'Glyph look (glyph_look): AUTOMATIC draws HUD 2\'s glyphs in its own tint; COLOURED gives them the buttons\' colours (Xbox letters, PlayStation shapes) at HUD 2\'s sizes.', only: 'pad' },
      { t: 'cmp', title: 'Glyph look on the classic HUD', cl: CAP('g_cl_look0'), h2: CAP('g_cl_look2'), ll: 'AUTOMATIC', rl: 'HUD 2 GLYPHS', cap: 'On the classic HUD AUTOMATIC uses the coloured glyphs; HUD 2 GLYPHS draws HUD 2\'s style (single rings, chamfered bumper pills) at the classic sizes. The family (Xbox / PlayStation / Nintendo) still follows Button prompts.', only: 'pad' },
      { t: 'keys' },
      { t: 'settings', title: 'Input and layout settings', keys: ['input_mode', 'glyph_style', 'glyph_look', 'confirm_button', 'pause_on_disconnect', 'pad_backend', 'pad_preset', 'weapon_groups', 'holds_as_toggles', 'aim_mode', 'aim_cone', 'invert_y', 'steer_expo', 'steer_scale', 'stick_deadzone', 'trigger_threshold', 'throttle_rate', 'rumble', 'auto_target', 'fire_target'] },
      { t: 'dev', html: `<p><b>Device switch</b> (UI_PLAN 6.2): the last valid input wins on unpaused game time - pad = any button, a trigger past 0.5, a stick past about 0.25 (drift never counts); keyboard and mouse = any key, about 8-10 px of motion at 1080p in one frame (DPI-scaled) or a wheel notch; after a switch the other device's axis-only signals are ignored for 300-500 ms. The HUD swaps in one frame (HUD 2 fades in over <code>hud_transition</code>), the cursor hides and hover is off in pad mode; a pad unplugged in flight pauses (<code>pause_on_disconnect</code>). <code>input_mode</code> locks a device.</p>
<p><b>Glyphs</b>: three families over one positional layout (south = confirm), FLvibed's own drawing in one atlas; detection by the XInput slot's HID vendor id (Sony 054C = PlayStation, Nintendo 057E = Nintendo, anything else Xbox; <code>glyphs.cpp</code>); no Steam Input type is read. <b>Presets</b> with tap / hold / double per input (<code>controller\\docs\\BINDINGS.md</code>); every FREELANCER binding verified by the key trace. Not built: the Bindings screen (<code>edit_bindings</code>: the presets apply, the button shows a note); the autopilot's goal queue. <span class="edonly">The interactive editor changes this page's spec (saved into the artifact), not the game.</span></p>` },
    ] },

  { id: 'subtitles', nav: 'Subtitles & movies', title: 'Subtitles and movies',
    lead: `Every spoken line of the story, the mission comms, the bars and the Neural Net appears as a subtitle with the speaker's name in their colour (Trent amber, story characters their own colour, everyone else by their stance toward you), timed on the speaker's words. In flight the dialogue sits in one sliding panel at the top centre with the speaker's portrait inside it; Neural Net lines get their own column at the right, coloured and pulsed by severity; ambient radio chatter goes to the game's chat window. In cutscenes and room scenes one speaker at a time sits inside the lower letterbox bar. Movies fit the screen with their aspect kept, and the intros are subtitled.`,
    dv: { same: 'Subtitles and movies are the same with every device; under HUD 2 the panel takes HUD 2\'s free band, under the classic HUD the game\'s.' },
    blocks: [
      { t: 'cmp', title: 'The dialogue panel with the portrait', cl: CAP('s_portrait_cl'), h2: CAP('s_portrait_h2'), ll: 'CLASSIC HUD', rl: 'HUD 2', cap: 'Fort Bush\'s police answers a dock request: the speaker\'s portrait (the game\'s own comm window, placed inside the panel), name and faction in colour, the line on two rows. Left: the classic HUD, with the Neural Net column top right (DOCK IN USE - ENTERING QUEUE). Lower left in both: a chatter line in the chat band.' },
      { t: 'gal', items: [
        { img: CAP('s_stack_h2'), title: 'Two speakers at once (HUD 2)', cap: 'When two lines overlap, both stay in the panel, one above the other; since 0.2.5 the newest stays full size and only the older ones shrink, more gently.' },
        { img: CAP('s_stack_new'), title: 'The stack settled (0.2.5)', cap: 'The newest line at full size, the older one smaller above it.' },
        { img: CAP('c_chat_normal'), title: 'Side chat: Normal (default)', cap: 'The side chat is smaller by default since 0.2.5.' },
        { img: CAP('c_chat_large'), title: 'Side chat: Large', cap: 'The old size, chosen with the chat_size setting.' },
        { img: CAP('s_stack_43'), title: 'Two speakers at once at 4:3', cap: '1600x1200: the stacked lines shrink together inside the narrower screen, each with its speaker\'s name.' },
        { img: CAP('s_nn_h2'), title: 'Neural Net column and chat band (HUD 2)', cap: 'A Neural Net line (SHIELDS LOW) in its column at the right, its colour and pulses by severity; comms in the chat band left; a long line wraps inside the panel (test line).' },
        { img: CAP('s_43_portrait_h2'), title: 'The portrait with its line at 4:3 (HUD 2)', cap: '1600x1200 at the largest subtitle size: where the rows beside the portrait would be too short, it sits above its line, centred, and the rows take the full width - the portrait never leaves its dialogue.' },
        { img: CAP('s_vanilla_portrait_cl'), title: 'Vanilla 1.1, classic HUD (1280x960)', cap: 'Without HDE\'s bar shift the panel sits below the centred maneuver bar; the comm portrait goes beside its line\'s box (Newark Station), not to the game\'s top-left place.' },
        { img: CAP('s_longname_cl'), title: 'Long names fit; the bar stays clear', cap: 'A 40-character name (test line) steps down in size, then would be cut with "..." - always inside the panel; the panel keeps clear of the whole maneuver bar including its frame (FLvibed\'s fifth button widens it).' },
      ] },
      { t: 'table', title: 'What is shown where', head: ['Source', 'Where', 'State'], rows: [
        ['Story cutscenes, room and bar scenes', 'Inside the lower letterbox bar, one speaker at a time, inline name, no backing (<code>letterbox_mode</code> 0)', OK()],
        ['Story lines, mission comms, NPCs speaking to you with their portrait', 'The top panel in flight with the portrait slot (<code>space_position</code> 2); a story line holds its place until its audio ends and chatter never replaces it; two speakers share the panel (when both voices play they stay together even past the panel\'s height limit - kept so for now); a line already fading gives its room first', OK('HDE 4K / 4:3, vanilla, vanilla + FLUF')],
        ['Neural Net', 'Its own column, severity colours and 1-2 pulses; under HUD 2 the lines play in flight with the NeuroNet box hidden, and a line HUD 2 shows as an alert appears there instead', OK()],
        ['NPC lines without their portrait: chatter (joined from pieces), broadcasts, announcements', 'The game\'s chat window (its log keeps every line; under HUD 2 also its comm feed), "Name · Faction" in the speaker\'s colour - never over a story line; <code>chat_all_dialogue</code> copies every story line there too (off by default)', OK() + ' (not yet typed in step with its pieces)'],
        ['Scene mixes: room scenes recorded as one track (19: the landing at Manhattan, Lonnigan on the pad, Syd\'s offer, the dig site, Tekagi\'s garden, Niemann\'s prison, Quintaine\'s lab ...)', 'Like any room scene: one speaker at a time with their name, paged on the spoken words, on the scene\'s own clock from the moment its sound starts; a skipped scene\'s lines leave with it - read from the game\'s scene state, also when a setup shows no letterbox bars. The text is a draft from the shooting script and speech to text, under review (<code>mixes.tsv</code>). A mod that plays its own recording under the same sound name gets no lines instead of the wrong ones: the file is checked against the original\'s size', UP() + ' ' + OK('HDE, the landing at Manhattan (New Game)')],
        ['Bases, conversations', 'Bottom centre, above the controller\'s prompt lane and under any open window', OK()],
        ['Intro movies', 'Inside the movie\'s lower bar; the HD intro, the original and the full Bonus DVD intro (the HD intro\'s launch radio exchange before "The war had been raging" ' + UP() + '); no backing box - the outline and shadow carry the text (an adaptive box that read frames from the video renderer broke the intro\'s audio). Drawn in a child window of the game window: window and display capture show them, OBS Game Capture does not (it sees no movie at all: movies play outside the game\'s Direct3D output)', OK('HDE 4K borderless, HDE 1600x1200 windowed, vanilla 1280x960')],
        ['Mission comms at 4:3, the comm portrait', 'The portrait stays with its line on every HUD: in HUD 2\'s panel beside the rows, or above its line where the rows would be too short; on the classic HUD without a top panel (vanilla: no bar shift) beside its line\'s box; the nav place only as the last resort. Speaker names (and name · faction) step down to the floor, then are cut with "..." inside the panel; the panel keeps clear of the maneuver bar\'s live edge including its frame. HUD 2\'s alert never meets the panel or the chat band', OK('HDE 4K / 1600x1200 / 1024x768 / 1280x720, vanilla 1280x960')],
        ['Spoken words', 'With <i>word_pop</i> each word grows a little as it is spoken; the growth is capped so the gaps between words always stay (a long word in HUD 2\'s narrow face once closed its space)', OK()],
      ] },
      { t: 'settings', title: 'Subtitle settings (SUBTITLES)', keys: ['enabled', 'size', 'font', 'text_color', 'shadow', 'background_style', 'background_opacity', 'speaker_names', 'speaker_colors', 'hostile_marker', 'story', 'comms', 'bar', 'neural_net', 'chatter', 'chat_all_dialogue', 'space_position', 'comm_portrait', 'hud_arrows', 'letterbox_mode', 'cinematic_single_speaker', 'motion', 'word_pop', 'neural_net_severity', 'stack_fit', 'linger', 'retire_delay'] },
      { t: 'settings', title: 'Movie settings (MOVIES)', keys: ['movie_fit', 'movie_skip', 'movie_intro', 'movie_subtitles'] },
      { t: 'dev', html: `<p><b>Sources:</b> comm receipt 0x4CE000, PlayArchetype 0x428680 (cutscenes, rooms, the Neural Net queue), Movie.dll imports for the intros; the text in <code>subtitles\\data\\subtitles.tsv</code> / <code>movies.tsv</code> / <code>word_times.tsv</code>, authored and reviewed in the private review repository and published here (never edited in FLvibed); <code>speaker_colors.tsv</code> and <code>movie_frames.tsv</code> owned here. Timing: pages on the speaker's words from the forced alignment, a reading minimum of 0.3 s per word (at least 1.25 s). Standards followed: sizes, background opacity, speaker names on their own row, line length and reading speed (<code>subtitles\\docs\\DISPLAY_PLAN.md</code>, <code>SUBTITLE_PRACTICES.md</code>).</p>
<p><b>Movies:</b> fitted through the filter graph's <code>IBasicVideo</code> (source = the picture area from <code>movie_frames.tsv</code>, destination = the largest centred rectangle of its aspect; the windows keep their size so capture tools are not disturbed), the subtitles drawn into a child window of the game window above the VMR-7's (WS_CLIPSIBLINGS; window region = the margins around the fitted picture + each line's box or only its text's pixels; the layered owned window stays as the fallback); Movie.dll's <code>Sleep(300)</code> in UpdateMovie is chained while a movie plays so the transitions run at the display rate; no box on movie lines (by design; the 64 x 36 luminance grid read from the renderer stalled playback - 8 frames drawn and 50 audio discontinuities in 75 s of the intro, measured 26 Oct 2026 - so the reads are off; debug <code>moviesample on</code>). The fonts come from <code>core\\game\\gamefont</code> (the game's faces on every build). <b>HUD 2:</b> the placements read HUD 2's free bands from the HUD bus (<code>core\\hud_bus.h</code>), the panel inside <code>topFree</code>, the Neural Net column under the target card (and below HUD 2's alert where it reaches in), the comm feed narrowed beside or ended above the alert; the maneuver bar shift and the comm window move come from the subtitles host (HostApi v4 / v5). <b>Top panel</b> (DISPLAY_PLAN): names through the one fit rule (<code>uidraw::FitText</code>, cached) inside the panel's own room (the rows beside the portrait, or the tab's room less the smallest portrait 0.05 H; the tab's two rows share the smaller size); the keep-out = the maneuver bar's rightmost shown button (incl. <code>FLvibedAutopilotButton</code>) plus its frame's ear 0.023 H, read live, with the panel + tab as one shape (else below the top row, <code>layout</code> tab-noroom); a panel too narrow for 20 characters beside the portrait puts it above its line; no top panel = the window beside its line's box. <b>Word pop:</b> <code>textfit::GrowCap</code> lets each side take at most a fifth of the space's advance (unit tests <code>tests\\textfit_test.cpp</code>). <b>Open:</b> chatter typed in step, the portrait at 21:9 not yet checked in game, movies in exclusive fullscreen, the review of the 19 scene mixes (the dialogue text itself is fully reviewed, 1 Nov 2026). Code <code>subtitles\\src\\impl\\display.*</code>, <code>movie.*</code>; module map <code>subtitles\\CLAUDE.md</code>.</p>` },
    ] },

  { id: 'autopilot', nav: 'Autopilot', title: 'The Advanced Autopilot (work in progress)',
    lead: `FLvibed's own autopilot can take the ship and play: follow the mission objective, travel by lanes and gates, dock (also skipping the docking scene), keep station, escort and fight - with the countermeasures, nanobots, batteries, missiles and loot handled by need. It names what it does and why on the HUD. Hold View for half a second on the pad (or press K / the maneuver bar's fifth button) to hand it the ship - both start the same thing: the mission objective if there is one, else your waypoints (across systems), else what suits the target (setting <i>Autopilot start</i>); press it again, or any stick input past the hand-back threshold, to take it back. Everything it does works the same on the pad and on keyboard and mouse. It is <b>work in progress</b>: its current target is speedrun-grade play of every story mission, and the way it shares control with the player is not designed yet.`,
    dv: { pad: 'On the pad: View held starts / stops it; X opens the goal panel while it flies; LB the target picker, LB held the action wheel.', km: 'With keyboard and mouse: key K or the maneuver bar\'s fifth button starts / stops it; Shift+K or Shift + click on that button opens the goal panel (the same rows; arrows and Enter, Tab for the tabs, Esc closes, or click a row). The HUD shows the game\'s maneuver area with AUTOPILOT lit. You target with the game\'s own contact list (or HUD 2\'s): the pad\'s target picker and action wheel have no mouse twin.' },
    blocks: [
      { t: 'cmp', title: 'The autopilot flying', cl: CAP('p_ap_cl'), h2: CAP('p_ap_h2'), ll: 'CLASSIC HUD', rl: 'HUD 2', cap: 'Left: the classic HUD\'s status line under the maneuver bar (AUTOPILOT · TRAVEL TO FORT BUSH · 2.0 KM), the cyan engage ring, the legend\'s autopilot rows (HAND BACK, GOALS, AUTOPILOT OFF). Right: HUD 2\'s AUTOPILOT chip in the nav (DOCK, with its ETA) and GOALS / TAKE CONTROL in the left lane.' },
      { t: 'gal', title: 'Its controls on the pad', items: [
        { img: CAP('p_goals'), title: 'The goal panel (X while it flies; Shift+K on the keyboard)', cap: 'ACTIONS: dock at, travel to, fly to the target, the mission objective, travel along the waypoints, hold here - each with what it will do. QUEUE and DO NEXT are greyed: there is no goal queue yet. On keyboard and mouse the same panel shows its keys at its foot and every row, tab and the ESC mark are clickable.' },
        { img: CAP('p_picker'), title: 'The target picker (LB)', cap: 'Categories on the bumpers (threats, mission, navigation, ships, loot), rows with distance and the action A starts.' },
        { img: CAP('p_wheel'), title: 'The action wheel (LB held)', cap: 'Quick actions on the right stick; since 0.2.5 more compact, each command on a HUD 2 plate over a see-through disc.' },
        { img: CAP('w_wheel_classic'), title: 'The action wheel under the classic HUD', cap: 'The game\'s own panel look, lighter than before.' },
      ] },
      { t: 'table', title: 'What it does', head: ['Part', 'What it does today'], rows: [
        ['<b>Modes</b>', 'Mission objective (the story\'s own trigger conditions read live), travel (lanes, gates, jump holes; route round minefields and damage zones), dock (fast dock, the queue shortcut, the docking scene skipped), hold (keep station, nose on the scene), escort / follow, fight (target choice by threat and odds, missiles by economy, evasion).'],
        ['<b>Knowledge</b>', 'Every behaviour names its source: what you have seen, general skill, hidden game data, community tricks. The preset decides: COMPETENT knows only what you have seen; SPEEDRUN knows everything the game data tells.'],
        ['<b>Reflexes</b>', 'Countermeasures against homing missiles, repairs by need, loot worth the detour, self-defence - under every goal.'],
        ['<b>Weapons</b> ' + UP(), 'Every gun that can reach the target fires, also while the ship circles a station or generator with the nose elsewhere; at a station or generator it holds far enough off that every gun can point at it; a friendly ship holds the guns only when it is close to the line of fire, and never one behind a generator, whose hull takes the misses (options <code>fire_covering</code>, <code>static_hold_guns</code>, <code>lof_caution</code>).'],
        ['<b>Time on target</b> ' + UP(), 'It finishes the enemy it is on before the next attacker; against a ship flying at it, it reverses, turns ahead of the pass, slides the pass wide and keeps firing while its shield lasts; it keeps a distance where a crossing enemy cannot outturn it and learns the best distance for each pair of ships from its own fights; missiles at moving ships aim where the target will be and leave out of an afterburner run; at stations, generators and capital ships every launcher fires as soon as it has reloaded. It rolls toward the angle where more of its guns reach the target and finishes the roll, and barrel-rolls with a sideways dodge when that costs no gun; it steers true while rolled (the game turns a ship relative to its view, not the rolled ship); it never launches again from where its own missile burst on it (options <code>finish_target</code>, <code>headon_reverse</code>, <code>standoff</code>, <code>missile_lead</code>, <code>roll_guns</code>, <code>roll_commit</code>, <code>roll_flair</code>, <code>steer_level</code>, <code>self_burst</code>).'],
        ['<b>Flight manners</b> ' + UP(), 'A ship left banked by a turn or a fight levels off smoothly by rolling while it travels, docks, follows or waits, the nose staying on its way (option <code>level_off</code>): the camera stays level. Following a leader that waits (a story scene), the ship rests behind it instead of asking the game to follow again and again, so the free-flight button no longer blinks; when the game keeps ending a follow (a slow or far leader, an escort), the autopilot keeps the follow position itself (<code>follow_own</code>). Docks at a station bay brake to what the way in allows instead of ramming the station at cruise speed (<code>bay_arrive</code>), and a dock the game stops flying at a moving ship is lined up again (<code>dock_regain</code>). Banking into turns is built and stable but off by default (<code>roll_bank</code>: about 0.2 s slower a turn).'],
        ['<b>Escapes and huge targets</b> ' + UP(), 'In an escape mission it pursues nothing before the first jump out: it fights only what shoots at it and waits by the mission\'s next place (<code>survival_calm</code>, <code>survival_until_jump</code>, <code>survival_stage</code>); in speedrun mode it already heads for the next objective while the story still talks (<code>prestage_next</code>). At a huge static target (the Dyson city\'s generators) it cruises in, kills the engine still in cruise, coasts in firing its missiles and torpedoes, stops at weapons range and aims at the hull in front of it (<code>big_coast</code>; never at a moon, planet, sun, lane or gate). A follow or a Hold you started defends itself (<code>follow_defend</code>, <code>hold_defend</code>).'],
        ['<b>Hand-off</b>', 'Starts from the player\'s live state (ship, reputation, choices) - after a save is loaded mid-session from that save\'s own mission goal, title and markers, never the previous mission\'s ' + UP() + '; any stick past <code>autopilot_cancel</code>, the hold or the key hands back; a cyan / amber reticle ring marks each change.'],
      ] },
      { t: 'table', title: 'Status: the speedrun benchmark (docs\\SPLITS.md, 24 Oct 2026)', head: ['', 'Par (fastest recorded run)', 'Our best', 'Gap'], rows: [
        ['All 14 legs (M01a-M13)', '10,047 s', '12,867 s', '+2,820 s'],
        ['Closest', 'M12 348 s', '354 s', '+6 s'],
        ['Furthest', 'M13 686 s', '1,192 s', '+507 s (1 full pass)'],
        ['Others over +190 s', 'M07, M02, M05, M10, M09, M06, M11', '', '+419 / +258 / +251 / +210 / +195 / +193 / +191 s'],
      ] },
      { t: 'p', html: `<b>Known failures (open work):</b> docking at moving ships; an M12 death in the second generator hold; M11 fails about half its runs (Zone 21 mines); deaths in M13; guard jitter; the M04 Mactan dock (it waits too long for the dock to unlock).` },
      { t: 'settings', title: 'Autopilot settings (AUTOPILOT)', keys: ['preset', 'knowledge', 'engage', 'auto_fire', 'missiles', 'countermeasures', 'repair', 'loot', 'caution', 'avoid', 'fast_dock', 'skip_dock_scene', 'autopilot_cancel', 'autopilot_key', 'start_smart', 'maneuver_button'] },
      { t: 'dev', html: `<p><b>Docs:</b> <code>controller\\docs\\AUTOPILOT.md</code> (as built: every behaviour, setting, measurement), <code>AUTOPILOT_UX.md</code> (the product design: goal model, engagement policy, 2a knowledge sources and presets, 5 the in-game UI), <code>docs\\SPLITS.md</code> / <code>LEGS.md</code> / <code>LEG_DOSSIER.md</code> (benchmark), the remaining legs by gap. Code <code>controller\\src\\impl\\autopilot*.cpp</code> (one file per section), <code>goals.*</code>, <code>picker.*</code>, <code>wheel.*</code>, <code>barbutton.*</code>; <code>core\\game\\route.*</code>, <code>avoid.*</code>, <code>flight.*</code>, <code>ai.*</code>. Debug <code>ap start &lt;mode&gt; | stop | status | set | settings | preset ...</code> (<code>controller\\docs\\HARNESS.md</code>). Every new behaviour gets its own setting with a sane default (the later UI is cheap). Note: <code>knowledge</code>'s default is WHAT YOU HAVE SEEN; the legs apply <code>ap preset speedrun</code>.</p>` },
    ] },

  { id: 'options', nav: 'Options page', title: 'The FLvibed options page',
    lead: `All of FLvibed's settings live on one page inside the game's own Options screen: the FLVIBED button in the main menu's and the in-game Options (and the pause menu's sixth button). Five tabs - GENERAL, CONTROLLER, AUTOPILOT, SUBTITLES, MOVIES. Changes apply at once, CANCEL reverts what you changed since you opened the page, DEFAULT resets the tab, and <i>Show advanced settings</i> adds the tuning keys as named in the ini files. It works with mouse, keyboard and pad (D-pad rows, left / right adjust, LB / RB tabs). Try it live below, or read every row here.`,
    dv: { pad: 'The live page below shows the controller look with this pad\'s glyphs (prompts, focus).', km: 'The live page below shows the keyboard-and-mouse look (no prompt bar; click and hover).' },
    blocks: [
      { t: 'p', html: `<b>Text size</b> applies to the page itself: its words grow with <i>Text size</i> (CONTROLLER &gt; MENUS AND PROMPTS) while the page stays inside the Options screen's area - rows, tabs and buttons get taller, a word too long for its box steps down to the legibility floor before it is cut, and rows that no longer fit scroll. Below 100 % nothing shrinks: the words already stand at the floor. While the page is open nothing of HUD 2's menu context strip runs under it. The page is <b>opaque</b> in both looks, in the Options screen and on its own: nothing of the room behind shows through (a bar character's name label once did).` },
      { t: 'p', html: `<b>Help line:</b> the focused row's help stands at the top of the screen, right-aligned with the page, in up to three lines (0.78 H wide). ${UP()} A text that needs more widens its box to the screen's left margin (0.02 W) before anything is cut (0.1.0 cut the Rumble help's last words at 4:3); a very long help (over about 450 characters, e.g. FLUF's windows row) still loses its end at 4:3.` },
      { t: 'gal', items: [
        { img: CAP('o_4k_min'), title: 'In the Options screen, Text size 80 %', cap: '3840x2160: the page at its smallest (the label faces at the floor).' },
        { img: CAP('o_4k_max'), title: 'In the Options screen, Text size 150 %', cap: 'The same page at the largest size: taller rows, the bottom buttons inside the screen\'s frame.' },
        { img: CAP('o_43_max'), title: 'Standalone (pause menu) at 4:3, opaque', cap: '1600x1200, HUD 2 look: the page on its own opaque plate over the Manhattan bar - no room shows through; the strip hidden under it.' },
      ] },
      { t: 'tabs' },
      { t: 'dev', html: `<p><b>Text size</b> (FIX-TEXT 2): fonts by <code>uikit::FontsFor(sh, text_size)</code> (80..150, one font set shared with the pad screens), row pitch / tab and button heights x max(1, size), widths fixed; labels and captions through <code>uidraw::FitText</code>; the buttons grow upward. <b>Backing</b> (FIX-TEXT 3): standalone the classic panel and HUD 2's plate at full opacity; hosted, <code>options_page::RenderUnder</code> (the under-HUD pass) fills the game's translucent Options window frame with an opaque plate (the frame from <code>uiskin::PlateOffsets</code>), so the window keeps its look over a solid base. Under the page (standalone or hosted) and the on-screen keyboard the strip of <code>uistrip</code> hides (its modal check).</p>
<p>The page is drawn by the logic in the game's measured Options geometry (<code>options_page.cpp</code>, HUD 2 look under <code>ui_style</code> 1); rows come from the settings registries (<code>core\\settings.h</code>) through the settings bus, labels and options from <code>core\\ui_meta.h</code> (generated from <code>docs\\UI_SPEC.json</code> by <code>tools\\ui_meta.py</code>); ini keys = spec keys (<code>EXE\\FLController.ini</code> [Controller] / [Autopilot], <code>FLSubtitles.ini</code> [Subtitles], <code>FLvibed.ini</code> [Modules]). Native row controls are replicas (later refinement). The MOVIES Intro row offers only the files present. <code>docs\\SETTINGS.md</code> is the full generated reference.</p>` },
    ] },

  { id: 'speedrun', nav: 'Speedrun & New Game', title: 'New Game, speedrun mode and LiveSplit',
    lead: `NEW GAME asks one question: NORMAL GAME (the default), ASSISTED (the autopilot ready from the first mission) or SPEEDRUN MODE (an in-game timer with a split per story checkpoint, the autopilot's speedrun preset, and LiveSplit fed automatically). The choice is saved with the game, shown on its save slot and locked for that save. A starts, B backs out.`,
    dv: { same: 'The prompt and the timer are the same with every device (the prompt\'s pills show only with the controller; the mouse clicks the rows).' },
    blocks: [
      { t: 'gal', items: [
        { img: CAP('x_newgame_prompt_cl'), title: 'The New Game prompt', cap: 'One description line for the highlighted mode; the prompts at the bottom right.' },
        { img: CAP('p_timer'), title: 'The speedrun timer (classic HUD)', cap: 'Top right: the run time and the current split (M01A - CONTROL); on HUD 2 it sits under the target card.' },
      ] },
      { t: 'p', html: `In speedrun mode the timer shows the run time, the current split and the delta to your best. LiveSplit (1.8.29 or newer, Control &gt; Start TCP Server) gets start, splits, reset and loadless game time over its TCP server. FLvibed never calls its timer official.` },
      { t: 'settings', title: 'Speedrun settings (AUTOPILOT > SPEEDRUN MODE)', keys: ['speedrun_timer', 'livesplit', 'livesplit_port', 'livesplit_gametime'] },
      { t: 'dev', html: `<p>The mode per save in <code>EXE\\FLvibed\\saves.ini</code> (no game file touched), tagged on the load lists. LiveSplit: a TCP client to 127.0.0.1:<code>livesplit_port</code> (<code>starttimer</code> on the New Game click, <code>split</code> per checkpoint (<code>docs\\checkpoints.tsv</code>, compiled into <code>checkpoints_gen.h</code>) and at the final cutscene, <code>reset</code> on the main menu, <code>pausegametime</code> / <code>unpausegametime</code> around loads). The split detector agrees with <code>tools\\splits.py</code> on 193 / 193 recorded checkpoints; a live split from a real kill has not been observed. Splits and par: <code>docs\\SPLITS.md</code>, <code>docs\\livesplit\\</code>. Code <code>livesplit.*</code>, <code>runtimer.*</code>, <code>newgame.*</code>.</p>` },
    ] },

  { id: 'open', nav: 'Not implemented yet', title: 'Not implemented yet, and what is open',
    lead: `An honest list of what FLvibed does not do yet, what is built but unproven, and the questions still open. It is kept current with the work: an item leaves this list in the same change that builds it.`,
    dv: { same: 'This list covers every device; the controller-only items say so.' },
    blocks: [
      { t: 'table', title: 'The autopilot and the player', head: ['Item', 'State'], rows: [
        ['<b>Gameplay flow with the autopilot flying and the player on the guns.</b> There is no settled design for sharing control: who picks targets, how turret view (X held toggles it) and the ASSISTED layout behave while the autopilot manoeuvres, what the player\'s aim and fire do to its plan, how it hands back mid-fight. ASSISTED exists as a binding layout on the turret view, nothing more. Built so far (28 Oct 2026): X held switches turret view on and off while the autopilot flies, and the autopilot keeps full control - it steers, aims and fires on its own, whatever you look at (the reticle stays centred, the right stick only turns the camera and does not take the ship back).', WIP('not designed') + ' ' + UP('turret view under the autopilot: new in 0.2.0')],
        ['Every story leg at or under par (speedrun-grade): 2,820 s over par in total; M13 +507 s, M07 +419 s and more (Autopilot section).', WIP()],
        ['Known failures: moving-ship docks, the M12 generator-hold death, M11 Zone 21 mines (about 50 % failures), M13 deaths, guard jitter, the M04 Mactan dock.', WIP('open')],
        ['The goal queue (queue, do next, reorder): the panel\'s QUEUE / DO NEXT are greyed.', NO('not built')],
        ['Mouse versions of the target picker and the action wheel (keyboard and mouse target through the game\'s contact list; the wheel\'s autopilot item, AUTOPILOT GOALS, is Shift+K). On HUD 2\'s keyboard form the SHIFT+K GOALS prompt gives way to TAKE CONTROL where the line between the panels is short (16:9).', NO('not built')],
        ['The unattended campaign run (New Game to the end of the story).', NO('not reached')],
      ] },
      { t: 'table', title: 'Controller UI', head: ['Item', 'State'], rows: [        ['The Bindings screen (<code>edit_bindings</code>): the three presets apply; no remapping editor; CUSTOM = FREELANCER.', NO('not built')],
        ['The nav map\'s objects as controls: the stick drives the game\'s cursor, no D-pad snap to objects.', NO('not built')],
        ['The inventory\'s JETTISON hold and the equipment COMPARE line in the inventory.', NO('not built')],
        ['The real Elite pad in menus, bases, dealers, the OSK, the pickers (verified on the virtual pad only; a hands-on test on a real pad is pending); the K&amp;M half of the device switch verified by code and harness only.', NO()],
        ['A pad A on the game\'s own buttons out of focus goes through the virtual mouse\'s hover (a background game never recomputes it) on the screens without their own native click. Native now: the main menu, the multiplayer LAN / INTERNET prompt, the death dialog, the confirmation and the story popups (28 Oct 2026); the rest (dealers, NeuroNet windows) still by hover.', WIP('watch on the real pad')],
        ['Vibration beyond the first set: per-category strength sliders, trigger rumble (impulse triggers), DualSense effects and waveform, explosions, engine and afterburner rumble, missile-lock tick. The first set (hits, shield failure, hand-back, popup boxes) is built.', NO('not built') + ' ' + UP('first set: new in 0.2.0')],
        ['The SDL3 backend (<code>pad_backend</code> 1) with a real PlayStation or Switch Pro pad: built and tested on SDL\'s virtual pads only; the Xbox pad through SDL likewise.', NO('not verified') + ' ' + UP('experimental backend: new in 0.2.0')],
        ['HUD 2\'s layout presets: <b>Focus</b> (<code>hud_preset</code> 1, advanced row) is built and experimental; <b>Speedrun</b> and <b>Guided</b> are planned (the setting accepts 0 and 1 only).', WIP('Focus experimental; others planned')],
        ['The options page needs the controller module: with <code>controller = 0</code> in <code>FLvibed.ini</code> the page is gone (the subtitle settings are then changed in <code>EXE\\FLSubtitles.ini</code>).', NO('by design')],
        ['Rumble and ignoring the pad while the game is in the background: verified by the test harness only, not yet on a real pad.', NO('not verified')],
        ['HUD 2 and the game\'s target label: when a target sits behind HUD 2\'s target card on screen, the game\'s own name and health label for it can draw over the card.', WIP('known issue')],
        ['Native row controls on the options page are replicas; the Options button\'s caption is 1 px short at 720p.', WIP('refinement')],
        ['A pad button to skip story cutscenes in space (the game allows none); mines as player weapons (torpedoes and cruise disruptors on the missile button held, in every preset and under the autopilot: verified on the virtual pad, 4 Nov 2026); steering scale on ships other than the Starflier.', NO()],
      ] },
      { t: 'table', title: 'Multiplayer (new in 0.2.0)', head: ['Item', 'State'], rows: [
        ['Objectives, mission marks, job-board missions, mission results and HUD 2\'s dock replies in multiplayer: read where the game itself receives them (Freelancer.exe\'s client object - one path for single player and multiplayer). A job taken from the server\'s board: HUD 2\'s objective line, the autopilot\'s objective mode (lanes to the job\'s waypoint, its marked targets destroyed).', OK('local HDE server, 28 Oct 2026')],
        ['The docked strip in multiplayer: base name, ship, hold and prices from the game\'s own client data (the single-player server has none there).', OK('local HDE server, 28 Oct 2026')],
        ['The pad through the main menu, the LAN / INTERNET prompt (A picks, B back), the server list and the character list (D-pad rows, A connect / load, Y new character): the game\'s own buttons pressed directly (no simulated mouse click, so the test pad drives them in a background game too). The death dialog (focus on LOAD AUTOSAVE / RESPAWN, A presses the focused button) too.', OK('main menu, prompt, lists and both death dialogs on the virtual pad out of focus, 28 Oct 2026')],
        ['Your own comm lines in multiplayer carry your character\'s name (the game\'s player list).', OK('local HDE server, 28 Oct 2026')],
        ['How a server says what it allows: the chat tag - a server line that is the tag alone (a line that only mentions it, as FLHook\'s relay of a player\'s chat "Name: [flvibed ...]", is ignored: two clients, 28 Oct 2026) - and the FLHook plugin <code>flvibed_server.dll</code> for HD Edition\'s FLHook (<code>server\\flhook\\</code>: on / travel / off from one config file, its line kept out of the chat) - built and verified on the local server, 28 Oct 2026. FLUF payloads (server and client both on FLUF) next; the server name / description is ruled out as a channel.', WIP('FLUF not built')],
        ['Finer parts than on / travel / off; an on-screen note when a start is refused.', WIP('design decision pending')],
        ['Several clients on one server (two verified, 28 Oct 2026): per-client channels, logs, account sets and permission; other players\' ships in the contacts (character name and affiliation, as the game\'s own target label), targeting them, death / respawn and quitting while the other plays; a player\'s chat never sets the permission.', OK('two HDE clients on the local FLHook server')],
        ['Autopilot-led PvP between clients: fights, kills and deaths work; a player who fights you counts as a threat (the odds-aware exit leaves a lost fight in time); on a server the autopilot leans to survival - <code>mp_caution</code> 2 and <code>mp_flee</code> 0.4 (no reload in multiplayer: a lost ship is lost); a Hold defends itself (<code>hold_defend</code>); an experimental duel flight <code>pvp_duel</code> (off: it lost its first A/B rounds - an opponent who closes keeps the fight at point blank); the flight in a duel against an equally agile ship (evasion, the futile straight flee) and a stance from "destroy at all costs" to "survive at all costs" are the next design steps.', WIP('design decision pending')],
        ['A vanilla 1.1 client works with FLvibed (a job through the objective mode, the docked strip, names). Vanilla 1.1 lists a LAN server by its IPv6 address only and cannot connect to it; FLvibed lists IPv4 hosts there, as HD Edition and FLUF do - written only over vanilla\'s own bytes, so HD Edition\'s exe, FLUF or any other version of the fix is never overridden.', OK('local server, vanilla 1.1 client with FLvibed alone, 28 Oct 2026')],
        ['Internet and modded servers.', WIP('not tested')],
      ] },
      { t: 'table', title: 'HUD 2 and HUD 2 in the menus', head: ['Item', 'State'], rows: [
        ['The target brackets\' label and bars, the lead indicator and the off-screen arrows stay the game\'s (an indicator hook is not robust enough): the biggest gap in the centre.', WIP('decided for now')],
        ['The NeuroNet news dot (its flash state not found); the 5 s arrival line in a fight.', NO('open')],
        ['<b>Enemies sitting idle in a fight</b> (GitHub issue 3): not fixed. FLvibed logs the stalled hostile ships (<code>EXE\\FLvibed_npc_stalls.log</code>, <code>npc_stall_log</code>) and the cause is being investigated.', NO('open, investigating')],
        ['Y LAUNCH is not offered while Trent (your own character) holds the focus on the launch pad.', NO('open')],
        ['A bar offer at 4:3 / 16:10; the job board\'s native tooltip; the death dialog\'s and the main-menu load screen\'s side buttons.', NO()],
        ['The screens HUD 2 in the menus leaves native: main menu, loading screen, the nav map\'s drawing and frame, scroll bars, text sizes, the repair art, the confirm dialog\'s dimming box.', WIP('decided')],
        ['A narrower dealer bumper pill at 16:10 (a design call).', NO('open')],
      ] },
      { t: 'table', title: 'Not verified yet: checks that need a hands-on test in the game', head: ['Item', 'State'], rows: [
        ['FLUF, FLUF above FLvibed (order B): the palette run with keyboard focus (typing, the held keys, the pad on its list) - order A passed by hand.', NO('hands-on check open')],
        ['FLUF alone (FLvibed out of dacom.ini) with Alt+Enter: whether the freeze into exclusive fullscreen is FLUF\'s and the original game\'s alone.', NO('hands-on check open')],
        ['The game\'s tutorial boxes on the pad (A / B, the prompts) as a player meets them.', NO('hands-on check open')],
        ['The 0.2.6 pad changes (the tractor\'s A / X, the right stick\'s enemies-first press, the enemies cue, the weapon group editor, the NeuroNet cursor and the map zoom): tested on a virtual pad, not a real one. Not yet checked: the classic HUD\'s tractor rows on screen, the Focus preset, a ship with more than ten weapons, edited groups across a save and reload.', NO('hands-on check open')],
        ['The 0.2.7 pad changes (the torpedo and disruptor holds, Invert Y in turret view, the room bumpers): tested on a virtual pad, not a real one. Not run: the game\'s own Invert Y option switched on.', NO('hands-on check open')],
        ['The prompt flicker reported at the dealers with Neural Net subtitles (GitHub issue 10): a guard is in, but the flicker could not be reproduced, so it is not proven fixed. The report\'s own case, a gun bought into a free hardpoint, was not run.', NO('not reproduced')],
        ['HUD 2 in scenes: the chat\'s cards were read in game on a real docking and launch. Not run: a mission\'s story cutscene, and a Neural Net line during a cutscene.', NO('check open')],
        ['The game\'s NeuroNet box staying up beside HUD 2 after a load: a guard is in, but the fault could not be reproduced in 44 test loads, so it is not proven fixed.', NO('not reproduced')],
        ['FLvibed\'s borderless window by the player: Alt+Tab, Alt+Enter, a vanilla start configured for fullscreen (the mouse at the screen edges: fixed and tested by hand on HDE, 26 Oct 2026).', NO('hands-on check open')],
        ['Two speaking comms past the top panel\'s height limit stay together (the voice hold wins): kept so for now.', WIP('design decision pending')],
        ['The comm portrait\'s capture (a back-buffer read) stays on with the system\'s own Direct3D 8 (vanilla); under HDE\'s wrapper it is off, because there it broke every later device reset - whether vanilla is affected cannot be shown (the original game never retries a failed reset).', WIP('design decision pending')],
        ['Under HDE\'s wrapper the comm portrait is no longer held through its closing animation (a consequence of the above).', NO('follow-up')],
      ] },
      { t: 'table', title: 'Displays, compatibility, release', head: ['Item', 'State'], rows: [
        ['Exclusive fullscreen.', NO()],
        ['Movie subtitles in exclusive fullscreen; in an OBS Game Capture (it sees no movie at all; window / display capture works).', NO()],
        ['Vanilla Freelancer 1.1 beyond M01a (it runs the mod through the first mission); the newer HDE with FLSharp 0.9.2; Discovery; FLUF\'s notifications and its mission-briefing map, and FLUF modules beyond its debugger.', NO()],
        ['A live speedrun split from a real kill (the detector matches every recorded checkpoint).', NO()],
        ['Subtitles: chatter typed in step with its pieces; the review of the 19 scene mixes (the dialogue text itself is fully reviewed); the portrait at 21:9 not yet checked in game.', WIP()],
        ['A player guide - in the repository, on the GitHub wiki and as an in-game first-launch screen (the releases come with a player installer).', NO('planned')],
      ] },
      { t: 'dev', html: `<p>Sources: <code>docs\\UI_BUILD.md</code> 5, <code>docs\\UI_HUD2.md</code> / <code>UI_HUD2_EXTENDED.md</code> open items, <code>controller\\CLAUDE.md</code> "Not verified yet", <code>subtitles\\docs\\DISPLAY_PLAN.md</code> Next, <code>docs\\SPLITS.md</code>. Rule (<code>tools\\uimock\\README.md</code>): a change that builds or closes an item removes it here in the same work package.</p>` },
    ] },
];
